function policy(obs, params, mem) {
  if (!mem._i) {
    mem._i = 1;
    mem._ph = 0;
    mem._pt = obs.t;
    mem._r = 0;
  }
  const dt = Math.max(0.001, Math.min(obs.t - mem._pt, 0.05));
  mem._pt = obs.t;
  mem._r = Math.min(1, obs.t / 0.5);

  const P = params || [];
  const n = P.length;
  function p(i, d) { return i < n ? P[i] : d; }

  const freq = p(0, 1.2);
  const hipAmp = p(1, 0.3);
  const hipBase = p(2, 0);
  const kneeSw = p(3, 0.8);
  const kneeBs = p(4, 0.15);
  const ankAmp = p(5, 0.15);
  const ankBs = p(6, 0.05);
  const ankPh = p(7, 1.57);
  const pKp = p(8, 1.5);
  const pKd = p(9, 0.5);
  const rKp = p(10, 1.5);
  const rKd = p(11, 0.5);
  const yKp = p(12, 0.5);
  const hipFB = p(13, 1.0);
  const ankFB = p(14, 1.5);
  const hOutFB = p(15, 1.0);
  const aRollFB = p(16, 1.5);
  const wPt = p(17, 0.05);
  const armSw = p(18, 0.2);
  const elbB = p(19, 0.5);
  const Kp = p(20, 3.0);
  const Kd = p(21, 1.0);
  const hOutB = p(22, 0.05);
  const kneeFB = p(23, -0.1);
  const wPtFB = p(24, -0.5);

  mem._ph += 2 * Math.PI * freq * dt;
  if (mem._ph >= 2 * Math.PI) mem._ph -= 2 * Math.PI;

  const phL = mem._ph;
  const phR = mem._ph + Math.PI;

  const roll = obs.orientation[0];
  const pitch = obs.orientation[1];
  const yaw = obs.orientation[2];
  const gRoll = obs.gyro[0];
  const gPitch = obs.gyro[1];

  const pC = pKp * pitch + pKd * gPitch;
  const rC = rKp * roll + rKd * gRoll;
  const yC = yKp * yaw;

  const r = mem._r;
  const swL = Math.max(0, -Math.sin(phL));
  const swR = Math.max(0, -Math.sin(phR));
  const cL = Math.cos(phL);
  const cR = Math.cos(phR);

  const d = new Array(25).fill(0);

  // Waist
  d[0] = wPt + wPtFB * pC;
  d[1] = 0.2 * rC;
  d[2] = 0.2 * yC;

  // Left leg
  d[3] = hipAmp * r * cL + hipBase + hipFB * pC;
  d[4] = hOutB + hOutFB * rC;
  d[6] = kneeBs + kneeSw * r * swL + kneeFB * pC;
  d[7] = ankAmp * r * Math.sin(phL + ankPh) + ankBs + ankFB * pC;
  d[8] = aRollFB * rC;

  // Right leg
  d[14] = hipAmp * r * cR + hipBase + hipFB * pC;
  d[15] = hOutB + hOutFB * rC;
  d[17] = kneeBs + kneeSw * r * swR + kneeFB * pC;
  d[18] = ankAmp * r * Math.sin(phR + ankPh) + ankBs + ankFB * pC;
  d[19] = aRollFB * rC;

  // Arms (swing opposite to same-side leg)
  d[10] = -armSw * r * cL;
  d[13] = elbB;
  d[21] = -armSw * r * cR;
  d[24] = elbB;

  // PD position control → motor voltage commands
  const cmd = new Array(25);
  for (let i = 0; i < 25; i++) {
    let c = Kp * (d[i] - obs.joints[i]) - Kd * obs.speeds[i];
    cmd[i] = c < -1 ? -1 : c > 1 ? 1 : c;
    if (cmd[i] !== cmd[i]) cmd[i] = 0;
  }
  return cmd;
}

function learn(lab) {
  const N = 25;
  const maxT = 200;
  let t = 0;

  function g() {
    let u = Math.random(), v = Math.random();
    if (u < 1e-10) u = 1e-10;
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  const init = [
    1.2, 0.3, 0, 0.8, 0.15, 0.15, 0.05, 1.57,
    1.5, 0.5, 1.5, 0.5, 0.5,
    1.0, 1.5, 1.0, 1.5,
    0.05, 0.2, 0.5,
    3.0, 1.0, 0.05, -0.1, -0.5
  ];
  const sig = [
    0.2, 0.1, 0.05, 0.2, 0.1, 0.1, 0.05, 0.3,
    0.3, 0.15, 0.3, 0.15, 0.3,
    0.3, 0.3, 0.3, 0.3,
    0.05, 0.1, 0.2,
    1.0, 0.3, 0.05, 0.1, 0.2
  ];
  const lo = [
    0.3, 0, -0.3, 0, 0, 0, -0.3, -3.14,
    0, 0, 0, 0, 0,
    -3, -3, -3, -3,
    -0.3, 0, 0,
    0.5, 0, -0.2, -1, -1
  ];
  const hi = [
    3.0, 1.0, 0.3, 2.0, 1.0, 0.5, 0.3, 3.14,
    5, 3, 5, 3, 3,
    3, 3, 3, 3,
    0.3, 1.0, 2.0,
    15, 3, 0.2, 1, 1
  ];

  function ev(q) {
    if (t >= maxT) return -1e9;
    t++;
    const r = lab.trial(q);
    return r.distance + 0.01 * r.time;
  }

  let bp = init.slice();
  let bs = -1e9;

  try {
    bs = ev(init);
    let pop = [{ p: init.slice(), s: bs }];
    let gf = 1.0;

    while (t < maxT) {
      const lam = Math.min(12, maxT - t);
      if (lam <= 0) break;

      const cen = new Array(N).fill(0);
      for (const ind of pop) {
        for (let j = 0; j < N; j++) cen[j] += ind.p[j];
      }
      for (let j = 0; j < N; j++) cen[j] /= pop.length;

      let suc = 0;
      const off = [];
      for (let i = 0; i < lam; i++) {
        const mut = new Array(N);
        for (let j = 0; j < N; j++) {
          mut[j] = Math.max(lo[j], Math.min(hi[j], cen[j] + sig[j] * gf * g()));
        }
        const s = ev(mut);
        off.push({ p: mut, s: s });
        if (s > bs) {
          bs = s;
          bp = mut.slice();
          suc++;
        }
      }

      const comb = pop.concat(off);
      comb.sort(function(a, b) { return b.s - a.s; });
      pop = comb.slice(0, 4);

      if (suc / lam > 0.2) gf *= 1.15;
      else gf *= 0.85;
      if (gf > 5) gf = 5;
      if (gf < 0.01) gf = 0.01;
    }
  } catch (e) {}

  return bp;
}

function policy(obs, params, mem) {
  const P = params || [];
  const n = P.length;
  function p(i, d) { return i < n ? P[i] : d; }

  if (!mem.init) {
    mem.init = 1;
    mem.phase = 0;
    mem.prevT = obs.t;
  }

  const dt = Math.max(0.002, Math.min(obs.t - mem.prevT, 0.06));
  mem.prevT = obs.t;

  const freq = p(0, 1.0);
  const hipAmp = p(1, 0.35);
  const hipBase = p(2, 0.1);
  const kneeAmp = p(3, 0.5);
  const kneeBase = p(4, 0.15);
  const ankAmp = p(5, 0.15);
  const ankBase = p(6, -0.03);
  const ankPhase = p(7, 1.57);
  const armSwing = p(8, 0.3);
  const elbowBend = p(9, 0.4);
  const pitchKp = p(10, 3.0);
  const pitchKd = p(11, 1.0);
  const rollKp = p(12, 4.0);
  const rollKd = p(13, 1.5);
  const yawKp = p(14, 1.5);
  const yawKd = p(15, 0.5);
  const pAnkW = p(16, -0.5);
  const pHipW = p(17, -0.1);
  const pWaistW = p(18, -0.1);
  const rHipW = p(19, 0.4);
  const rAnkW = p(20, 0.25);
  const rWaistW = p(21, -0.1);
  const Kp = p(22, 5.0);
  const Kd = p(23, 2.0);
  const leanFwd = p(24, 0.03);
  const hipOutBase = p(25, 0.08);

  mem.phase += 2 * Math.PI * freq * dt;
  while (mem.phase >= 2 * Math.PI) mem.phase -= 2 * Math.PI;

  const roll = obs.orientation[0];
  const pitch = obs.orientation[1];
  const yaw = obs.orientation[2];
  const gRoll = obs.gyro[0];
  const gPitch = obs.gyro[1];
  const gYaw = obs.gyro[2];

  const pE = pitchKp * pitch + pitchKd * gPitch;
  const rE = rollKp * roll + rollKd * gRoll;
  const yE = yawKp * yaw + yawKd * gYaw;

  const ramp = Math.min(1, obs.t / 0.5);

  const phL = mem.phase;
  const phR = mem.phase + Math.PI;
  const cosL = Math.cos(phL);
  const sinL = Math.sin(phL);
  const cosR = Math.cos(phR);
  const sinR = Math.sin(phR);
  const swL = Math.max(0, -sinL);
  const swR = Math.max(0, -sinR);

  const d = new Array(25).fill(0);

  d[0] = leanFwd * ramp + pWaistW * pE;
  d[1] = rWaistW * rE;
  d[2] = -0.3 * yE;

  d[3] = (hipBase + hipAmp * cosL) * ramp + pHipW * pE;
  d[4] = hipOutBase + rHipW * rE;
  d[6] = (kneeBase + kneeAmp * swL) * ramp;
  d[7] = (ankBase + ankAmp * Math.sin(phL + ankPhase)) * ramp + pAnkW * pE;
  d[8] = rAnkW * rE;

  d[14] = (hipBase + hipAmp * cosR) * ramp + pHipW * pE;
  d[15] = hipOutBase - rHipW * rE;
  d[17] = (kneeBase + kneeAmp * swR) * ramp;
  d[18] = (ankBase + ankAmp * Math.sin(phR + ankPhase)) * ramp + pAnkW * pE;
  d[19] = -rAnkW * rE;

  d[10] = -armSwing * ramp * cosL;
  d[11] = 0.1 * ramp;
  d[13] = elbowBend * ramp;
  d[21] = -armSwing * ramp * cosR;
  d[22] = 0.1 * ramp;
  d[24] = elbowBend * ramp;

  const jLo = [-0.407,-0.342,-0.515,-0.567,-0.268,-0.544,-0.05,-0.748,-0.458,-0.392,-1.08,-0.183,-0.722,-0.05,-0.432,-0.265,-0.481,-0.05,-0.713,-0.375,-0.384,-1.149,-0.214,-0.775,-0.05];
  const jHi = [0.822,0.441,0.616,1.596,0.609,0.777,2.286,0.515,0.359,0.97,2.326,1.833,0.807,2.192,1.818,0.542,0.696,2.167,0.485,0.356,1.032,2.496,1.823,0.855,2.289];

  const cmd = new Array(25);
  for (let i = 0; i < 25; i++) {
    d[i] = Math.max(jLo[i], Math.min(jHi[i], d[i]));
    let c = Kp * (d[i] - obs.joints[i]) - Kd * obs.speeds[i];
    cmd[i] = Math.max(-1, Math.min(1, c));
    if (isNaN(cmd[i])) cmd[i] = 0;
  }
  return cmd;
}

function learn(lab) {
  const N = 26;
  const maxTrials = 200;
  let used = 0;

  function gauss() {
    let u = Math.random(), v = Math.random();
    if (u < 1e-10) u = 1e-10;
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  const init = [
    1.0, 0.35, 0.1, 0.5, 0.15, 0.15, -0.03, 1.57,
    0.3, 0.4,
    3.0, 1.0, 4.0, 1.5, 1.5, 0.5,
    -0.5, -0.1, -0.1, 0.4, 0.25, -0.1,
    5.0, 2.0, 0.03, 0.08
  ];

  const lo = [
    0.3, 0, -0.2, 0, -0.05, 0, -0.3, -3.14,
    0, 0,
    0.5, 0, 1.0, 0, 0, 0,
    -2, -2, -1, -2, -2, -1,
    1.0, 0.5, -0.1, 0
  ];
  const hi = [
    3.0, 1.0, 0.5, 1.5, 1.0, 0.5, 0.3, 3.14,
    1.0, 2.0,
    10.0, 5.0, 15.0, 8.0, 5.0, 3.0,
    2, 2, 1, 2, 2, 1,
    20.0, 10.0, 0.15, 0.3
  ];

  const sig = [
    0.15, 0.08, 0.04, 0.1, 0.06, 0.06, 0.03, 0.25,
    0.08, 0.08,
    0.5, 0.3, 0.75, 0.4, 0.4, 0.2,
    0.15, 0.15, 0.08, 0.15, 0.15, 0.08,
    1.0, 0.4, 0.01, 0.015
  ];

  function clamp(v, l, h) { return Math.max(l, Math.min(h, v)); }

  function evaluate(params) {
    if (used >= maxTrials) return -1e9;
    used++;
    try {
      const r = lab.trial(params);
      let score = r.distance + 0.15 * r.time;
      if (r.trace && r.trace.length > 2) {
        let ms = 0;
        for (const row of r.trace) {
          ms += row[4] * row[4] + row[5] * row[5];
        }
        ms /= r.trace.length;
        score -= 0.1 * ms;
      }
      return score;
    } catch(e) {
      return -1e9;
    }
  }

  let best = init.slice();
  let bestScore = evaluate(init);
  let prevScore = bestScore;

  const lam = 10;

  while (used < maxTrials) {
    const genLam = Math.min(lam, maxTrials - used);
    let genBest = null;
    let genBestScore = bestScore;

    for (let i = 0; i < genLam; i++) {
      const cand = new Array(N);
      for (let j = 0; j < N; j++) {
        cand[j] = clamp(best[j] + sig[j] * gauss(), lo[j], hi[j]);
      }
      const score = evaluate(cand);
      if (score > genBestScore) {
        genBestScore = score;
        genBest = cand;
      }
    }

    if (genBest) {
      best = genBest;
      bestScore = genBestScore;
    }

    const improved = bestScore > prevScore;
    prevScore = bestScore;

    const factor = improved ? 1.05 : 0.85;
    for (let j = 0; j < N; j++) {
      sig[j] *= factor;
      sig[j] = Math.max(0.002, Math.min(sig[j], (hi[j] - lo[j]) * 0.3));
    }
  }

  return best;
}

function policy(obs, params, mem) {
  var P = Array.isArray(params) ? params : [];
  if (!mem.init) { mem.init = 1; mem.phase = 0; mem.prevT = obs.t; }
  var dt = obs.t - mem.prevT;
  if (!(dt > 0.001)) dt = 0.002;
  if (dt > 0.06) dt = 0.06;
  mem.prevT = obs.t;
  function gp(i, lo, hi, df) {
    var v = (P.length > i && isFinite(P[i])) ? P[i] : df;
    return v < lo ? lo : v > hi ? hi : v;
  }
  var freq = gp(0, 0.3, 3, 1.0);
  var hipAmp = gp(1, 0, 0.8, 0.1);
  var kneeAmp = gp(2, 0, 1.2, 0.2);
  var leanFwd = gp(3, -0.05, 0.25, 0.03);
  var armSw = gp(4, 0, 0.8, 0.05);
  var kneeBase = gp(5, 0, 0.6, 0.2);
  var Kp = gp(6, 1, 8, 2.5);
  var Kd = gp(7, 0.1, 3, 1.0);
  var bS = gp(8, 0.5, 4, 2.0);
  var dT = gp(9, 0.01, 0.15, 0.08);
  var ankPG = 0.35 * bS;
  var ankRG = 0.4 * bS;
  var hipPG = -0.2 * bS;
  var hipRG = 0.25 * bS;
  var wstPG = -0.2 * bS;
  var wstRG = -0.15 * bS;
  var wstYG = -0.1 * bS;
  var pitch = obs.orientation[1];
  var roll = obs.orientation[0];
  var yaw = obs.orientation[2];
  var gP = obs.gyro[1], gR = obs.gyro[0], gY = obs.gyro[2];
  var pE = (pitch - leanFwd) + dT * gP;
  var rE = roll + dT * gR;
  var yE = yaw + dT * gY;
  mem.phase += 6.283185307179586 * freq * dt;
  while (mem.phase >= 6.283185307179586) mem.phase -= 6.283185307179586;
  var phL = mem.phase;
  var phR = mem.phase + 3.141592653589793;
  var ramp = (obs.t - 0.3) / 0.7;
  if (ramp < 0) ramp = 0;
  if (ramp > 1) ramp = 1;
  var cL = Math.cos(phL), sL = Math.sin(phL);
  var cR = Math.cos(phR), sR = Math.sin(phR);
  var swL = sL > 0 ? sL : 0;
  var swR = sR > 0 ? sR : 0;
  var d = new Array(25).fill(0);
  d[0] = wstPG * pE;
  d[1] = wstRG * rE;
  d[2] = wstYG * yE;
  d[3] = (0.05 - hipAmp * cL) * ramp + hipPG * pE;
  d[4] = 0.07 + hipRG * rE;
  d[6] = kneeBase + kneeAmp * swL * ramp;
  d[7] = 0.02 - 0.15 * hipAmp * cL * ramp + ankPG * pE;
  d[8] = -ankRG * rE;
  d[14] = (0.05 - hipAmp * cR) * ramp + hipPG * pE;
  d[15] = 0.07 - hipRG * rE;
  d[17] = kneeBase + kneeAmp * swR * ramp;
  d[18] = 0.02 - 0.15 * hipAmp * cR * ramp + ankPG * pE;
  d[19] = ankRG * rE;
  d[10] = -armSw * cL * ramp;
  d[13] = 0.3;
  d[21] = -armSw * cR * ramp;
  d[24] = 0.3;
  var jLo = [-0.407,-0.342,-0.515,-0.567,-0.268,-0.544,-0.05,-0.748,-0.458,-0.392,-1.08,-0.183,-0.722,-0.05,-0.432,-0.265,-0.481,-0.05,-0.713,-0.375,-0.384,-1.149,-0.214,-0.775,-0.05];
  var jHi = [0.822,0.441,0.616,1.596,0.609,0.777,2.286,0.515,0.359,0.97,2.326,1.833,0.807,2.192,1.818,0.542,0.696,2.167,0.485,0.356,1.032,2.496,1.823,0.855,2.289];
  var cmd = new Array(25);
  for (var i = 0; i < 25; i++) {
    if (d[i] < jLo[i]) d[i] = jLo[i];
    if (d[i] > jHi[i]) d[i] = jHi[i];
    var j = obs.joints[i], s = obs.speeds[i];
    if (!isFinite(j)) j = 0;
    if (!isFinite(s)) s = 0;
    var c = Kp * (d[i] - j) - Kd * s;
    if (!isFinite(c)) c = 0;
    if (c > 1) c = 1;
    if (c < -1) c = -1;
    cmd[i] = c;
  }
  return cmd;
}
function learn(lab) {
  var N = 10, maxTrials = 200, used = 0;
