      var r = lab.trial(params);
      return 2 * r.distance + 0.5 * r.time + (r.time > 9.5 ? 2 : 0);
    } catch(e) { return -1e9; }
  }
  var best = inits[0].slice();
  var bestScore = evaluate(best);
  for (var ii = 1; ii < inits.length; ii++) {
    var sc = evaluate(inits[ii]);
    if (sc > bestScore) { bestScore = sc; best = inits[ii].slice(); }
  }
  var lam = 10, succCount = 0, genCount = 0;
  while (used < maxTrials) {
    var genLam = Math.min(lam, maxTrials - used);
    if (genLam <= 0) break;
    var improved = false;
    genCount++;
    for (var gi = 0; gi < genLam; gi++) {
      var cand = new Array(N);
      for (var jj = 0; jj < N; jj++) {
        cand[jj] = best[jj] + sig[jj] * gauss();
        if (cand[jj] < lo[jj]) cand[jj] = lo[jj];
        if (cand[jj] > hi[jj]) cand[jj] = hi[jj];
      }
      var sc = evaluate(cand);
      if (sc > bestScore) { bestScore = sc; best = cand.slice(); improved = true; }
    }
    if (improved) succCount++;
    if (genCount % 5 === 0 && used < maxTrials) {
      var rand = new Array(N);
      for (var jj = 0; jj < N; jj++) rand[jj] = lo[jj] + Math.random() * (hi[jj] - lo[jj]);
      var sc = evaluate(rand);
      if (sc > bestScore) { bestScore = sc; best = rand.slice(); }
    }
    if (genCount % 2 === 0) {
      var rate = succCount / 2;
      var factor = rate > 0.5 ? 1.15 : rate > 0.2 ? 1.0 : 0.85;
      for (var jj = 0; jj < N; jj++) {
        sig[jj] *= factor;
        var mx = (hi[jj] - lo[jj]) * 0.3;
        if (sig[jj] > mx) sig[jj] = mx;
        if (sig[jj] < 0.001) sig[jj] = 0.001;
      }
      succCount = 0;
    }
  }
  return best;
