  var Kp = gp(0, 0.5, 5, 2);
  var Kd = gp(1, 0.5, 3, 1.5);
  var ankleP = gp(2, 1, 8, 2.5);
  var ankleR = gp(3, 1, 8, 2.5);
  var waistP = gp(4, 0.3, 3, 1);
  var waistR = gp(5, 0.3, 3, 1);
  var gyroP = gp(6, 0.1, 1.5, 0.5);
  var gyroR = gp(7, 0.1, 1.5, 0.5);
  var stepFreq = gp(8, 0, 1.5, 0.5);
  var stepAmp = gp(9, 0, 0.3, 0.12);
  var kneeBend = gp(10, 0.05, 0.35, 0.18);
  var stanceWidth = gp(11, 0.05, 0.25, 0.15);

  var roll = obs.orientation[0]; if (!isFinite(roll)) roll = 0;
  var pitch = obs.orientation[1]; if (!isFinite(pitch)) pitch = 0;
  var yaw = obs.orientation[2]; if (!isFinite(yaw)) yaw = 0;
  var gR = obs.gyro[0]; if (!isFinite(gR)) gR = 0;
  var gP = obs.gyro[1]; if (!isFinite(gP)) gP = 0;
  var gY = obs.gyro[2]; if (!isFinite(gY)) gY = 0;

  var af = 0.5;
  mem.fGP = af * gP + (1 - af) * mem.fGP;
  mem.fGR = af * gR + (1 - af) * mem.fGR;
  var beta = 0.92;
  mem.fP = beta * (mem.fP + mem.fGP * dt) + (1 - beta) * pitch;
  mem.fR = beta * (mem.fR + mem.fGR * dt) + (1 - beta) * roll;

  var lf = obs.feet[0]; if (!isFinite(lf) || lf < 0) lf = 0;
  var rf = obs.feet[1]; if (!isFinite(rf) || rf < 0) rf = 0;
