  var rE = mem.fR + gyroR * mem.fGR;
  var yE = yaw + 0.1 * gY;

  mem.iP += pE * dt;
  mem.iR += rE * dt;
  if (mem.iP > 0.3) mem.iP = 0.3;
  if (mem.iP < -0.3) mem.iP = -0.3;
  if (mem.iR > 0.3) mem.iR = 0.3;
  if (mem.iR < -0.3) mem.iR = -0.3;
  pE += 0.2 * mem.iP;
  rE += 0.2 * mem.iR;

