  rE = Math.max(-1, Math.min(1, rE));
  yE = Math.max(-1, Math.min(1, yE));

  mem.phase += 2 * Math.PI * stepFreq * dt;
  if (mem.phase >= 2 * Math.PI) mem.phase -= 2 * Math.PI;

  var poseRamp = Math.min(1, obs.t / 0.5);
  var gaitRamp = Math.min(1, Math.max(0, (obs.t - 0.8) / 1.2));
  var phL = mem.phase;
  var phR = mem.phase + Math.PI;

