  var adaptBoost = 1 + Math.max(0, errMag - 0.15) * 2;
  var gAmp = stepAmp * gaitRamp * Math.min(2, adaptBoost);

  var d = new Array(25);
  for (var i = 0; i < 25; i++) d[i] = 0;

  d[4] = stanceWidth * poseRamp;
  d[6] = kneeBend * poseRamp;
  d[15] = stanceWidth * poseRamp;
  d[17] = kneeBend * poseRamp;
  d[13] = 0.15 * poseRamp;
  d[24] = 0.15 * poseRamp;

  d[3] += gAmp * Math.cos(phL);
  d[6] += gAmp * 0.3 * Math.max(0, -Math.sin(phL));
  d[7] += -gAmp * 0.15 * Math.max(0, Math.sin(phL));
  d[14] += gAmp * Math.cos(phR);
  d[17] += gAmp * 0.3 * Math.max(0, -Math.sin(phR));
  d[18] += -gAmp * 0.15 * Math.max(0, Math.sin(phR));
  d[10] = -0.3 * gAmp * Math.cos(phL);
  d[21] = -0.3 * gAmp * Math.cos(phR);

  var leftSwing = (mem.phase >= Math.PI);
  var catchP = Math.max(0, Math.abs(pE) - 0.12) * 0.5 * gaitRamp;
  var catchR = Math.max(0, Math.abs(rE) - 0.12) * 0.3 * gaitRamp;
  if (leftSwing) {
    d[3] += catchP * (pE > 0 ? 1 : -1);
    d[4] += catchR * (rE > 0 ? -1 : 1);
  } else {
    d[14] += catchP * (pE > 0 ? 1 : -1);
    d[15] += catchR * (rE > 0 ? 1 : -1);
  }

  if (obs.ground && obs.ground.length >= 5) {
    var g06 = obs.ground[4];
    if (isFinite(g06)) {
      var tAdj = 0.15 * Math.max(-0.2, Math.min(0.3, g06)) * gaitRamp;
      d[6] += tAdj;
      d[17] += tAdj;
    }
  }

  var bal = new Array(25);
  for (var i = 0; i < 25; i++) bal[i] = 0;

  bal[7] = -ankleP * pE * lw;
  bal[18] = -ankleP * pE * rw;
  bal[0] = -waistP * pE;
  bal[8] = ankleR * rE * lw;
  bal[19] = -ankleR * rE * rw;
  bal[1] = -waistR * rE;
  bal[2] = -0.2 * yE;

  var jLo = [-0.407,-0.342,-0.515,-0.567,-0.268,-0.544,-0.05,-0.748,-0.458,-0.392,-1.08,-0.183,-0.722,-0.05,-0.432,-0.265,-0.481,-0.05,-0.713,-0.375,-0.384,-1.149,-0.214,-0.775,-0.05];
  var jHi = [0.822,0.441,0.616,1.596,0.609,0.777,2.286,0.515,0.359,0.97,2.326,1.833,0.807,2.192,1.818,0.542,0.696,2.167,0.485,0.356,1.032,2.496,1.823,0.855,2.289];

  var cmd = new Array(25);
  for (var i = 0; i < 25; i++) {
    d[i] = Math.max(jLo[i], Math.min(jHi[i], d[i]));
    var j = obs.joints[i]; if (!isFinite(j)) j = 0;
    var s = obs.speeds[i]; if (!isFinite(s)) s = 0;
    var c = Kp * (d[i] - j) - Kd * s + bal[i];
    if (!isFinite(c)) c = 0;
    if (c > 1) c = 1;
    if (c < -1) c = -1;
    cmd[i] = c;
  }
  return cmd;
}

function learn(lab) {
