      var r = lab.trial(params);
      if (!r) return -1e9;
      if (r.outcome === "exploit" || r.outcome === "invalid" || r.outcome === "error") return -1e9;
      return r.distance + 0.1 * r.time;
    } catch(e) { return -1e9; }
  }

  var inits = [
    [2, 1.5, 2.5, 2.5, 1, 1, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 3, 3, 1.5, 1.5, 0.3, 0.3, 0, 0, 0.3, 0.2],
    [3, 2, 2, 2, 0.5, 0.5, 0.8, 0.8, 0, 0, 0.25, 0.2],
    [2, 1, 4, 4, 2, 2, 0.3, 0.3, 0, 0, 0.3, 0.2],
    [1.5, 2, 3, 3, 1, 1, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0.5, 0.15, 0.18, 0.15],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0.7, 0.2, 0.18, 0.15],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 1.0, 0.25, 0.15, 0.12],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0.4, 0.12, 0.2, 0.18],
    [3, 1, 2, 2, 1.5, 1.5, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 5, 5, 0.5, 0.5, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 1.5, 1.5, 2, 2, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 3, 3, 1, 1, 1.0, 1.0, 0, 0, 0.2, 0.15],
    [2, 1.5, 3, 3, 1, 1, 0.2, 0.2, 0, 0, 0.2, 0.15],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0, 0, 0.15, 0.08],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0, 0, 0.35, 0.25],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0.3, 0.1, 0.2, 0.15],
    [2, 2, 3, 3, 1, 1, 0.3, 0.3, 0, 0, 0.18, 0.15],
    [2, 1, 3, 3, 1, 1, 0.7, 0.7, 0, 0, 0.18, 0.15],
    [2.5, 1.2, 3, 3, 1, 1, 0.5, 0.5, 0.5, 0.15, 0.2, 0.15],
    [1, 1.5, 4, 4, 1, 1, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [4, 2, 2, 2, 0.5, 0.5, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 6, 6, 1, 1, 0.5, 0.5, 0, 0, 0.2, 0.15],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0, 0, 0.1, 0.05],
    [2, 1.5, 3, 3, 1, 1, 0.5, 0.5, 0, 0, 0.25, 0.2]
