  }
  if (!best) best = inits[0].slice();

  var sig = [];
  for (var j = 0; j < N; j++) sig[j] = (hi[j] - lo[j]) * 0.1;

  var genCount = 0, succCount = 0;
  while (used < maxTrials && lab.timeLeft() > 5) {
    var lam = Math.min(10, maxTrials - used);
    if (lam <= 0) break;
    genCount++;
    var improved = false;
    for (var gi = 0; gi < lam; gi++) {
      var cand = new Array(N);
      for (var jj = 0; jj < N; jj++) cand[jj] = clamp(best[jj] + sig[jj] * gauss(), jj);
      var sc = evaluate(cand);
      if (sc > bestScore) { bestScore = sc; best = cand.slice(); improved = true; }
    }
    if (improved) succCount++;
    if (genCount % 3 === 0) {
      var rate = succCount / 3;
      var factor = rate > 0.3 ? 1.15 : rate > 0.1 ? 1.0 : 0.82;
      for (var jj = 0; jj < N; jj++) {
