        sig[jj] = Math.max(0.003, Math.min((hi[jj] - lo[jj]) * 0.25, sig[jj]));
      }
      succCount = 0;
    }
    if (genCount % 6 === 0 && used < maxTrials - 24 && lab.timeLeft() > 20) {
      for (var ci = 0; ci < N && used < maxTrials; ci++) {
        var step = (hi[ci] - lo[ci]) * 0.08;
        for (var dir = -1; dir <= 1; dir += 2) {
          if (used >= maxTrials) break;
          var cand2 = best.slice();
          cand2[ci] = clamp(best[ci] + dir * step, ci);
          var sc2 = evaluate(cand2);
          if (sc2 > bestScore) { bestScore = sc2; best = cand2.slice(); }
        }
      }
    }
  }
  return best;
}

function policy(obs, params, mem) {
  const PI = Math.PI;
  const TAU = 2 * PI;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const finite = x => typeof x === "number" && Number.isFinite(x);
  const read = (a, i, fallback) => {
    const x = a && a[i];
    return finite(x) ? x : fallback;
  };
  const mod = x => {
    x %= TAU;
    return x < 0 ? x + TAU : x;
  };

  if (!mem || typeof mem !== "object") mem = {};

  const x = params && Array.isArray(params.x)
    ? params.x
    : (Array.isArray(params) ? params : []);
  const gene = (i, center, scale) =>
    center + scale * clamp(finite(x[i]) ? x[i] : 0, -1, 1);

  const freq = clamp(gene(0, 1.35, 0.65), 0.7, 2.0);
  const hipAmp = gene(1, 0.40, 0.24);
  const hipBias = gene(2, 0.0, 0.10);
  const harmonic = gene(3, 0.0, 0.22);
  const kneeAmp = clamp(gene(4, 0.55, 0.40), 0.05, 1.05);
  const kneeBase = clamp(gene(5, 0.035, 0.065), -0.04, 0.12);
  const toeLift = Math.max(0, gene(6, 0.13, 0.13));
  const ankleCouple = clamp(gene(7, 0.62, 0.37), -0.15, 1.0);
  const armAmp = Math.max(0, gene(8, 0.28, 0.28));
  const leanBase = gene(9, 0.035, 0.105);
  const hipK = Math.max(0, gene(10, 0.38, 0.48));
  const hipD = Math.max(0, gene(11, 0.10, 0.14));
  const waistK = gene(12, 0.75, 0.50);
  const rollK = gene(13, 0.60, 0.55);
  const outBias = Math.max(0, gene(14, 0.04, 0.065));
  const phaseOffset = gene(15, 0, 0.35);
  const servoK = gene(16, 1.0, 0.35);
  const servoD = gene(17, 1.0, 0.50);

  const filt = (key, value, alpha) => {
    if (!finite(mem[key])) mem[key] = value;
    else mem[key] += alpha * (value - mem[key]);
    return mem[key];
  };

  const orientation = obs && obs.orientation;
  const gyro = obs && obs.gyro;
  const roll = filt("_roll", read(orientation, 0, 0), 0.28);
  const pitch = filt("_pitch", read(orientation, 1, 0), 0.28);
  const yaw = filt("_yaw", read(orientation, 2, 0), 0.28);
  const gx = filt("_gx", read(gyro, 0, 0), 0.40);
  const gy = filt("_gy", read(gyro, 1, 0), 0.40);
  const gz = filt("_gz", read(gyro, 2, 0), 0.40);

  const forces = obs && obs.feet;
  const forceL = filt("_forceL", Math.max(0, read(forces, 0, 0)), 0.35);
  const forceR = filt("_forceR", Math.max(0, read(forces, 1, 0)), 0.35);
  const threshold = Math.max(12, 0.10 * (forceL + forceR));
  const contactL = forceL > threshold;
  const contactR = forceR > threshold;

  const ground = obs && obs.ground;
  const gh = (row, col) => read(ground, 3 * row + col, 0);
  const distances = [0.3, 0.6, 1.0, 1.5, 2.0, 3.0];
  const heights = [
    gh(0, 1), gh(1, 1), gh(2, 1),
    gh(3, 1), gh(4, 1), gh(5, 1)
  ];
  let meanD = 0;
  let meanH = 0;
  for (let i = 0; i < distances.length; i++) {
    meanD += distances[i];
    meanH += heights[i];
  }
  meanD /= distances.length;
  meanH /= heights.length;
  let numerator = 0;
  let denominator = 0;
  for (let i = 0; i < distances.length; i++) {
    numerator += (distances[i] - meanD) * (heights[i] - meanH);
    denominator += (distances[i] - meanD) * (distances[i] - meanD);
  }
  const slope = clamp(denominator > 0 ? numerator / denominator : 0, -0.65, 0.65);
  const terrainPitch = Math.atan(slope);
  const terrainLean = clamp(leanBase + 0.18 * terrainPitch, -0.14, 0.22);

  const upL = Math.max(
    0, gh(0, 0), gh(0, 1), gh(1, 0), gh(1, 1)
  );
  const upR = Math.max(
    0, gh(0, 1), gh(0, 2), gh(1, 1), gh(1, 2)
  );
  const clearL = clamp(1.65 * upL, 0, 0.55);
  const clearR = clamp(1.65 * upR, 0, 0.55);
  const terrainRoll = Math.atan(clamp((gh(1, 0) - gh(1, 2)) / 0.8, -0.6, 0.6));

  const now = read(obs, "t", 0);
  let phase;
  if (finite(mem._phase)) {
    const lastT = finite(mem._phaseT) ? mem._phaseT : now;
    const dt = clamp(now - lastT, 0, 0.08);
    phase = mod(mem._phase + TAU * freq * dt);
  } else {
    phase = mod(phaseOffset);
  }
  mem._phaseT = now;

  const wasAirL = typeof mem._airL === "boolean" ? mem._airL : !contactL;
  const wasAirR = typeof mem._airR === "boolean" ? mem._airR : !contactR;
  const landedL = contactL && wasAirL;
  const landedR = contactR && wasAirR;
  const sBefore = Math.sin(phase);
  if (landedL && sBefore > 0.25) {
    const target = PI - 0.04;
    phase = mod(phase + 0.75 * Math.max(0, target - phase));
  } else if (landedR && sBefore < -0.25) {
    const target = TAU - 0.04;
    phase = mod(phase + 0.75 * Math.max(0, target - phase));
