  mem._airL = !contactL;
  mem._airR = !contactR;
  mem._phase = phase;

  const s = Math.sin(phase);
  const wave = s + harmonic * Math.sin(2 * phase);
  const swingL = Math.pow(Math.max(0, s), 0.82);
  const swingR = Math.pow(Math.max(0, -s), 0.82);
  const ramp = clamp(now / 0.28, 0, 1);

  const pitchError = clamp(pitch - terrainLean, -0.9, 0.9);
  const hipCorrection = clamp(hipK * pitchError + hipD * gy, -0.30, 0.30);
  const hipL = ramp * (hipBias + hipAmp * wave) + hipCorrection;
  const hipR = ramp * (hipBias - hipAmp * wave) + hipCorrection;

  const kneeL = kneeBase + ramp * (
    kneeAmp * swingL +
    clearL * swingL +
    (contactL ? 0.12 * swingL : 0)
  );
  const kneeR = kneeBase + ramp * (
    kneeAmp * swingR +
    clearR * swingR +
    (contactR ? 0.12 * swingR : 0)
  );

  const ankleBalance = clamp(-0.16 * pitchError - 0.06 * gy, -0.18, 0.18);
  const ankleL = ankleCouple * (kneeL - hipL) +
    toeLift * ramp * swingL + ankleBalance + 0.28 * terrainPitch;
  const ankleR = ankleCouple * (kneeR - hipR) +
    toeLift * ramp * swingR + ankleBalance + 0.28 * terrainPitch;

  const lateral = clamp(0.52 * roll + 0.10 * gx, -0.18, 0.18);
  const twist = 0.035 - 0.16 * yaw - 0.04 * gz;
  const ankleRollL = 0.35 * terrainRoll - 0.06 * roll - 0.025 * gx;
  const ankleRollR = -0.35 * terrainRoll - 0.06 * roll - 0.025 * gx;
  const armSwing = ramp * armAmp * wave;

  const targets = new Array(25).fill(0);
  targets[0] = -waistK * pitchError - 0.10 * gy;
  targets[1] = -rollK * roll - 0.10 * gx;
  targets[2] = -0.45 * yaw - 0.08 * gz;

  targets[3] = hipL;
  targets[4] = outBias - lateral;
  targets[5] = twist;
  targets[6] = kneeL;
  targets[7] = ankleL;
  targets[8] = ankleRollL;
  targets[9] = 0;

  targets[10] = -armSwing;
  targets[11] = 0.05;
  targets[12] = 0;
  targets[13] = 0.18;

  targets[14] = hipR;
  targets[15] = outBias + lateral;
  targets[16] = twist;
  targets[17] = kneeR;
  targets[18] = ankleR;
  targets[19] = ankleRollR;
  targets[20] = 0;

  targets[21] = armSwing;
  targets[22] = 0.05;
  targets[23] = 0;
  targets[24] = 0.18;

  const lo = [
    -0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05,
    -0.748, -0.458, -0.392, -1.08, -0.183, -0.722, -0.05,
    -0.432, -0.265, -0.481, -0.05, -0.713, -0.375, -0.384,
    -1.149, -0.214, -0.775, -0.05
  ];
  const hi = [
    0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286,
    0.515, 0.359, 0.97, 2.326, 1.833, 0.807, 2.192,
    1.818, 0.542, 0.696, 2.167, 0.485, 0.356, 1.032,
    2.496, 1.823, 0.855, 2.289
  ];
  const kp = [
    3.6, 3.5, 2.5, 2.5, 2.8, 2.0, 3.8, 2.8, 2.8, 1.6,
    2.4, 2.2, 1.8, 2.0, 2.5, 2.8, 2.0, 3.8, 2.8, 2.8,
    1.6, 2.4, 2.2, 1.8, 2.0
  ];
  const kd = [
    0.24, 0.22, 0.18, 0.18, 0.18, 0.14, 0.24, 0.17, 0.17, 0.10,
    0.16, 0.16, 0.13, 0.14, 0.18, 0.18, 0.14, 0.24, 0.17, 0.17,
    0.10, 0.16, 0.16, 0.13, 0.14
  ];

  const joints = obs && obs.joints;
  const speeds = obs && obs.speeds;
  const commands = new Array(25);
  for (let i = 0; i < 25; i++) {
    const target = clamp(targets[i], lo[i] + 0.003, hi[i] - 0.003);
    const q = read(joints, i, 0);
    const v = read(speeds, i, 0);
    commands[i] = clamp(
      kp[i] * servoK * (target - q) - kd[i] * servoD * v,
      -1, 1
    );
  }
  return commands;
}

function learn(lab) {
