    try {
      if (typeof lab.timeLeft === "function") {
        const left = lab.timeLeft();
        if (finite(left) && left < 1.0) return false;
      }
    } catch (e) {}
    return true;
  };

  const scoreResult = result => {
    if (!result) return -1000000;
    const outcome = result.outcome;
    if (outcome === "exploit" || outcome === "invalid" || outcome === "error") {
      return -1000000;
    }
    const distance = finite(result.distance) ? result.distance : 0;
    const time = finite(result.time) ? clamp(result.time, 0, 10) : 0;
    let score = distance;
    if (outcome === "finished") score += 1.25;
    else score += 0.04 * time;
    if (finite(result.energy) && result.energy > 0) {
      score -= Math.min(0.12, result.energy * 0.000001);
    }
    return finite(score) ? score : -1000000;
  };

  const identity = () => {
    const a = new Array(n);
    for (let i = 0; i < n; i++) {
      a[i] = new Array(n).fill(0);
      a[i][i] = 1;
    }
    return a;
  };

  const eigen = matrix => {
    const a = new Array(n);
    const b = identity();
    for (let i = 0; i < n; i++) {
      a[i] = new Array(n);
      for (let j = 0; j < n; j++) {
        a[i][j] = 0.5 * (matrix[i][j] + matrix[j][i]);
      }
    }

    for (let iteration = 0; iteration < 8 * n * n; iteration++) {
      let p = 0;
      let q = 1;
      let largest = 0;
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          const v = Math.abs(a[i][j]);
          if (v > largest) {
            largest = v;
            p = i;
            q = j;
          }
        }
      }
      if (largest < 1e-11) break;

      const app = a[p][p];
      const aqq = a[q][q];
      const apq = a[p][q];
      const tau = (aqq - app) / (2 * apq);
      const sign = tau >= 0 ? 1 : -1;
      const t = sign / (Math.abs(tau) + Math.sqrt(1 + tau * tau));
      const c = 1 / Math.sqrt(1 + t * t);
      const s = t * c;

      for (let k = 0; k < n; k++) {
        if (k !== p && k !== q) {
          const akp = a[k][p];
          const akq = a[k][q];
          a[k][p] = c * akp - s * akq;
          a[p][k] = a[k][p];
          a[k][q] = s * akp + c * akq;
          a[q][k] = a[k][q];
        }
        const bkp = b[k][p];
        const bkq = b[k][q];
        b[k][p] = c * bkp - s * bkq;
        b[k][q] = s * bkp + c * bkq;
      }
      a[p][p] = app - t * apq;
      a[q][q] = aqq + t * apq;
      a[p][q] = 0;
      a[q][p] = 0;
    }

    const d = new Array(n);
    for (let i = 0; i < n; i++) d[i] = Math.sqrt(Math.max(1e-8, a[i][i]));
    return { b: b, d: d };
  };

  const inverseSqrtTimes = (v, e) => {
    const tmp = new Array(n).fill(0);
    const out = new Array(n).fill(0);
    for (let j = 0; j < n; j++) {
      for (let i = 0; i < n; i++) tmp[j] += e.b[i][j] * v[i];
      tmp[j] /= e.d[j];
    }
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) out[i] += e.b[i][j] * tmp[j];
    }
    return out;
  };

  const normal = () => {
    const u = Math.max(1e-12, Math.random());
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

  let mean = new Array(n).fill(0);
  let covariance = identity();
  let sigma = 0.42;
  let pathSigma = new Array(n).fill(0);
  let pathC = new Array(n).fill(0);
  let bestX = new Array(n).fill(0);
  let bestScore = -Infinity;
  let evaluations = 0;
  let generation = 0;
  let firstPopulation = true;

  const muWeights = new Array(mu);
  let weightSum = 0;
  for (let i = 0; i < mu; i++) {
    muWeights[i] = Math.log(mu + 0.5) - Math.log(i + 1);
    weightSum += muWeights[i];
  }
  for (let i = 0; i < mu; i++) muWeights[i] /= weightSum;

  let squaredWeightSum = 0;
  for (let i = 0; i < mu; i++) squaredWeightSum += muWeights[i] * muWeights[i];
  const muEff = 1 / squaredWeightSum;

  const cSigma = (muEff + 2) / (n + muEff + 5);
  const cC = (4 + muEff / n) / (n + 4 + 2 * muEff / n);
  const c1 = 2 / (Math.pow(n + 1.3, 2) + muEff);
  const cMu = Math.max(
    0,
    Math.min(1 - c1, 2 * (muEff - 2 + 1 / muEff) / (Math.pow(n + 2, 2) + muEff))
  );
  const damping = 1 + 2 * Math.max(
    0,
    Math.sqrt((muEff - 1) / (n + 1)) - 1
  ) + cSigma;
  const chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));

  while (evaluations < budget && canContinue()) {
    const eig = eigen(covariance);
    const population = [];
    const count = Math.min(lambda, budget - evaluations);
    let stopped = false;

    for (let k = 0; k < count; k++) {
      if (!canContinue()) {
        stopped = true;
        break;
      }

      let candidate;
      if (firstPopulation && k === 0) {
        candidate = mean.slice();
      } else {
        const z = new Array(n);
        const scaled = new Array(n);
        for (let j = 0; j < n; j++) {
          z[j] = normal();
          scaled[j] = eig.d[j] * z[j];
        }
        candidate = new Array(n).fill(0);
        for (let i = 0; i < n; i++) {
          let step = 0;
          for (let j = 0; j < n; j++) step += eig.b[i][j] * scaled[j];
          candidate[i] = clamp(mean[i] + sigma * step, -1, 1);
        }
      }

      let result;
      try {
        result = lab.trial({ x: candidate.slice() });
      } catch (e) {
        stopped = true;
        break;
      }
      evaluations++;

      const fit = scoreResult(result);
      population.push({ x: candidate.slice(), fit: fit });
      if (fit > bestScore) {
        bestScore = fit;
        bestX = candidate.slice();
      }
    }

    firstPopulation = false;
    if (population.length < mu) break;
    population.sort((a, b) => b.fit - a.fit);

    const oldMean = mean.slice();
    const newMean = new Array(n).fill(0);
    for (let k = 0; k < mu; k++) {
      for (let i = 0; i < n; i++) newMean[i] += muWeights[k] * population[k].x[i];
    }
    mean = newMean.map(v => clamp(v, -1, 1));

    const yMean = new Array(n);
    for (let i = 0; i < n; i++) yMean[i] = (mean[i] - oldMean[i]) / sigma;
    const whitened = inverseSqrtTimes(yMean, eig);
    for (let i = 0; i < n; i++) {
      pathSigma[i] = (1 - cSigma) * pathSigma[i] +
        Math.sqrt(cSigma * (2 - cSigma) * muEff) * whitened[i];
    }

    let pathNorm = 0;
    for (let i = 0; i < n; i++) pathNorm += pathSigma[i] * pathSigma[i];
    pathNorm = Math.sqrt(pathNorm);
    generation++;
    const normalization = Math.sqrt(1 - Math.pow(1 - cSigma, 2 * generation));
    const hsig = pathNorm / Math.max(1e-12, normalization) / chiN <
      1.4 + 2 / (n + 1) ? 1 : 0;

    for (let i = 0; i < n; i++) {
      pathC[i] = (1 - cC) * pathC[i] +
        hsig * Math.sqrt(cC * (2 - cC) * muEff) * yMean[i];
    }

    const nextCovariance = new Array(n);
    for (let i = 0; i < n; i++) nextCovariance[i] = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        let rankMu = 0;
        for (let k = 0; k < mu; k++) {
          const yi = (population[k].x[i] - oldMean[i]) / sigma;
          const yj = (population[k].x[j] - oldMean[j]) / sigma;
          rankMu += muWeights[k] * yi * yj;
        }
        nextCovariance[i][j] =
          (1 - c1 - cMu) * covariance[i][j] +
          c1 * (pathC[i] * pathC[j] +
            (1 - hsig) * cC * (2 - cC) * covariance[i][j]) +
          cMu * rankMu;
      }
    }
    for (let i = 0; i < n; i++) {
      nextCovariance[i][i] = Math.max(1e-8, nextCovariance[i][i]);
    }
    covariance = nextCovariance;

    sigma *= Math.exp((cSigma / damping) * (pathNorm / chiN - 1));
    sigma = clamp(sigma, 0.035, 0.85);

    if (stopped || population.length < count) break;
  }

  if (!finite(bestScore) || bestScore < -100000) bestX = new Array(n).fill(0);
  return { x: bestX };
}

function policy(obs, params, mem) {
  const PI = Math.PI;
  const TAU = 2 * PI;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = v => typeof v === "number" && Number.isFinite(v);
  const read = (a, i, fallback) => {
    const v = a && a[i];
    return finite(v) ? v : fallback;
  };
  const mod = v => {
    v %= TAU;
    return v < 0 ? v + TAU : v;
  };

  if (!mem || typeof mem !== "object") mem = {};

  const x = params && Array.isArray(params.x)
    ? params.x
    : (Array.isArray(params) ? params : []);
  const gene = (i, center, scale) =>
    center + scale * clamp(finite(x[i]) ? x[i] : 0, -1, 1);

  const freq = clamp(gene(0, 0.95, 0.35), 0.55, 1.45);
  const hipAmp = clamp(gene(1, 0.30, 0.23), 0.06, 0.55);
  const hipBias = gene(2, 0.01, 0.10);
  const duty = clamp(gene(3, 0.41, 0.075), 0.32, 0.49);
  const kneeAmp = clamp(gene(4, 0.55, 0.27), 0.18, 0.88);
  const kneeBase = clamp(gene(5, 0.02, 0.04), -0.04, 0.08);
  const ankleCouple = clamp(gene(6, 0.88, 0.34), 0.45, 1.30);
  const armAmp = Math.max(0, gene(7, 0.22, 0.24));
  const leanBase = gene(8, 0.02, 0.08);
  const hipP = clamp(gene(9, 0.72, 0.48), 0.15, 1.25);
  const hipD = Math.max(0, gene(10, 0.11, 0.16));
  const waistP = clamp(gene(11, 0.86, 0.58), 0.18, 1.50);
  const waistD = Math.max(0.02, gene(12, 0.16, 0.12));
  const rollP = clamp(gene(13, 0.75, 0.50), 0.20, 1.30);
  const outBias = clamp(gene(14, 0.07, 0.045), 0.015, 0.15);
  const phaseOffset = PI * (clamp(gene(15, 0, 1), -1, 1) + 1);
  const servoK = clamp(gene(16, 1.0, 0.28), 0.65, 1.35);
  const servoD = clamp(gene(17, 1.0, 0.35), 0.50, 1.50);

  const filt = (key, value, alpha) => {
    if (!finite(mem[key])) mem[key] = value;
    else mem[key] += alpha * (value - mem[key]);
    return mem[key];
  };

  const now = read(obs, "t", 0);
  const orientation = obs && obs.orientation;
  const gyro = obs && obs.gyro;

  const roll = filt("_roll", read(orientation, 0, 0), 0.36);
  const pitch = filt("_pitch", read(orientation, 1, 0), 0.36);
  const yaw = filt("_yaw", read(orientation, 2, 0), 0.30);
  const gx = filt("_gx", read(gyro, 0, 0), 0.52);
  const gy = filt("_gy", read(gyro, 1, 0), 0.52);
  const gz = filt("_gz", read(gyro, 2, 0), 0.48);

  const forces = obs && obs.feet;
  const forceL = filt("_forceL", Math.max(0, read(forces, 0, 0)), 0.40);
  const forceR = filt("_forceR", Math.max(0, read(forces, 1, 0)), 0.40);
  const contactThreshold = Math.max(15, 0.12 * (forceL + forceR));
  const contactL = forceL > contactThreshold;
  const contactR = forceR > contactThreshold;

  const ground = obs && obs.ground;
  const gh = (row, col) => read(ground, 3 * row + col, 0);
  const distances = [0.3, 0.6, 1.0, 1.5, 2.0, 3.0];
  const weights = [1.4, 1.25, 1.05, 0.80, 0.55, 0.30];
  const heights = new Array(6);
  let sumW = 0;
  let sumD = 0;
  let sumH = 0;
  for (let i = 0; i < 6; i++) {
    heights[i] = gh(i, 1);
    sumW += weights[i];
    sumD += weights[i] * distances[i];
    sumH += weights[i] * heights[i];
  }
  const meanD = sumD / Math.max(1e-8, sumW);
  const meanH = sumH / Math.max(1e-8, sumW);
  let slopeNum = 0;
  let slopeDen = 0;
  for (let i = 0; i < 6; i++) {
    slopeNum += weights[i] * (distances[i] - meanD) * (heights[i] - meanH);
    slopeDen += weights[i] * (distances[i] - meanD) * (distances[i] - meanD);
  }
  const slope = clamp(slopeDen > 1e-8 ? slopeNum / slopeDen : 0, -0.55, 0.55);
  const terrainPitch = Math.atan(slope);
  const terrainLean = clamp(leanBase + 0.15 * terrainPitch, -0.14, 0.17);
  const terrainRoll = Math.atan(clamp((gh(1, 0) - gh(1, 2)) / 0.8, -0.50, 0.50));

  const upL = Math.max(0, gh(0, 0), gh(0, 1), gh(1, 0), gh(1, 1));
  const upR = Math.max(0, gh(0, 1), gh(0, 2), gh(1, 1), gh(1, 2));
  const clearL = clamp(1.40 * upL, 0, 0.48);
  const clearR = clamp(1.40 * upR, 0, 0.48);

  let phase;
  if (finite(mem._phase)) {
    const lastT = finite(mem._phaseT) ? mem._phaseT : now;
    const dt = clamp(now - lastT, 0, 0.08);
    phase = mod(mem._phase + TAU * freq * dt);
  } else {
    phase = mod(phaseOffset);
  }

  let airL = typeof mem._airL === "boolean" ? mem._airL : !contactL;
  let airR = typeof mem._airR === "boolean" ? mem._airR : !contactR;
  let airSinceL = finite(mem._airSinceL) ? mem._airSinceL : now;
  let airSinceR = finite(mem._airSinceR) ? mem._airSinceR : now;
  let landedL = false;
  let landedR = false;

  if (!contactL) {
    if (!airL) airSinceL = now;
    airL = true;
  } else {
    if (airL && now - airSinceL > 0.055) landedL = true;
    airL = false;
  }
  if (!contactR) {
    if (!airR) airSinceR = now;
    airR = true;
  } else {
    if (airR && now - airSinceR > 0.055) landedR = true;
    airR = false;
  }

  const angleError = v => mod(v + PI) - PI;
  const phaseLock = 0.34;
  if (landedL && !landedR) {
    const err = angleError(TAU * duty - phase);
    if (Math.abs(err) < 0.80 * PI) phase = mod(phase + phaseLock * err);
  } else if (landedR && !landedL) {
    const err = angleError(PI + TAU * duty - phase);
    if (Math.abs(err) < 0.80 * PI) phase = mod(phase + phaseLock * err);
  }

  mem._phase = phase;
  mem._phaseT = now;
  mem._airL = airL;
  mem._airR = airR;
  mem._airSinceL = airSinceL;
  mem._airSinceR = airSinceR;

  const legPattern = u => {
    let r;
    let h;
    let swing = 0;
    if (u < duty) {
      r = clamp(u / duty, 0, 1);
      h = -Math.cos(PI * r);
      swing = Math.pow(Math.max(0, Math.sin(PI * r)), 0.80);
    } else {
      r = clamp((u - duty) / (1 - duty), 0, 1);
      h = Math.cos(PI * r);
    }
    return [h, swing];
  };

  const uL = phase / TAU;
  let uR = uL + 0.5;
  if (uR >= 1) uR -= 1;
  const gaitL = legPattern(uL);
  const gaitR = legPattern(uR);

  const rampU = clamp(now / 0.30, 0, 1);
  const ramp = rampU * rampU * (3 - 2 * rampU);
  const pitchError = clamp(pitch - terrainLean, -0.85, 0.85);
  const hipCorrection = clamp(hipP * pitchError + hipD * gy, -0.30, 0.30);
  const hipL = ramp * (hipBias + hipAmp * gaitL[0]) + hipCorrection;
  const hipR = ramp * (hipBias + hipAmp * gaitR[0]) + hipCorrection;

  const kneeL = ramp * (kneeBase + (kneeAmp + clearL) * gaitL[1]);
  const kneeR = ramp * (kneeBase + (kneeAmp + clearR) * gaitR[1]);

  const ankleBalance = clamp(-0.12 * pitchError - 0.035 * gy, -0.16, 0.16);
  const ankleL = ankleCouple * (kneeL - hipL) +
    ankleBalance + ramp * 0.10 * gaitL[1] + 0.15 * terrainPitch;
  const ankleR = ankleCouple * (kneeR - hipR) +
    ankleBalance + ramp * 0.10 * gaitR[1] + 0.15 * terrainPitch;

  const lateral = clamp(0.55 * roll + 0.12 * gx, -0.18, 0.18);
  const twist = clamp(0.02 - 0.16 * yaw - 0.035 * gz, -0.18, 0.18);
  const ankleRollL = 0.16 * terrainRoll - 0.055 * roll - 0.02 * gx;
  const ankleRollR = -0.16 * terrainRoll - 0.055 * roll - 0.02 * gx;

  const targets = new Array(25).fill(0);
  targets[0] = clamp(-waistP * pitchError - waistD * gy, -0.38, 0.38);
  targets[1] = clamp(-rollP * roll - 0.14 * gx, -0.38, 0.38);
  targets[2] = clamp(-0.38 * yaw - 0.06 * gz, -0.30, 0.30);

  targets[3] = hipL;
  targets[4] = outBias - lateral;
  targets[5] = twist;
  targets[6] = kneeL;
  targets[7] = ankleL;
  targets[8] = ankleRollL;
  targets[9] = ramp * 0.08 * gaitL[1];

  targets[10] = -ramp * armAmp * gaitL[0];
  targets[11] = 0.04;
  targets[12] = 0;
  targets[13] = 0.16;

  targets[14] = hipR;
  targets[15] = outBias + lateral;
  targets[16] = twist;
  targets[17] = kneeR;
  targets[18] = ankleR;
  targets[19] = ankleRollR;
  targets[20] = ramp * 0.08 * gaitR[1];

  targets[21] = -ramp * armAmp * gaitR[0];
  targets[22] = 0.04;
  targets[23] = 0;
  targets[24] = 0.16;

  const lo = [
    -0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05,
    -0.748, -0.458, -0.392, -1.08, -0.183, -0.722, -0.05,
    -0.432, -0.265, -0.481, -0.05, -0.713, -0.375, -0.384,
    -1.149, -0.214, -0.775, -0.05
  ];
  const hi = [
    0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286,
    0.515, 0.359, 0.97, 2.326, 1.833, 0.807, 2.192,
    1.818, 0.542, 0.696, 2.167, 0.485, 0.356, 1.032,
    2.496, 1.823, 0.855, 2.289
  ];
  const kp = [
    3.6, 3.5, 2.5, 2.5, 2.8, 2.0, 3.8, 2.8, 2.8, 1.6,
    2.4, 2.2, 1.8, 2.0, 2.5, 2.8, 2.0, 3.8, 2.8, 2.8,
    1.6, 2.4, 2.2, 1.8, 2.0
  ];
  const kd = [
    0.24, 0.22, 0.18, 0.18, 0.18, 0.14, 0.24, 0.17, 0.17, 0.10,
    0.16, 0.16, 0.13, 0.14, 0.18, 0.18, 0.14, 0.24, 0.17, 0.17,
    0.10, 0.16, 0.16, 0.13, 0.14
  ];

  const joints = obs && obs.joints;
  const speeds = obs && obs.speeds;
  const commands = new Array(25);
  for (let i = 0; i < 25; i++) {
    const target = clamp(targets[i], lo[i] + 0.003, hi[i] - 0.003);
    const q = read(joints, i, 0);
    const v = read(speeds, i, 0);
    commands[i] = clamp(
      kp[i] * servoK * (target - q) - kd[i] * servoD * v,
      -1, 1
    );
  }
  return commands;
}

