    make({ 0: 0.20, 1: -0.15, 4: -0.70, 9: 0.65, 11: 0.35, 12: 0.45, 15: 0.25 }),
    make({ 0: -0.15, 1: 0.65, 2: 0.20, 3: 0.40, 4: 0.20, 10: 0.50, 15: -0.10 }),
    make({ 0: 0.30, 1: 0.05, 4: 0.50, 5: -0.35, 8: -0.30, 13: 0.35, 15: 0.85 }),
    make({ 0: -0.45, 1: -0.25, 4: 0.05, 9: 0.80, 10: 0.65, 11: 0.55, 12: 0.35, 13: 0.30, 16: -0.35, 17: 0.35, 15: 0.05 }),
    make({ 0: 0.10, 1: 0.35, 3: -0.60, 4: 0.30, 7: -0.30, 8: 0.50, 11: -0.25, 15: -0.95 }),
    make({ 0: -0.25, 1: 0.10, 3: 0.10, 4: -0.50, 6: 0.25, 9: 0.10, 10: -0.30, 12: 0.60, 17: 0.40, 15: 0.95 })
  ];

  let evaluations = 0;
  let stopped = false;
  let bestScore = -Infinity;
  let bestX = zero.slice();

  const evaluate = candidate => {
    if (evaluations >= budget || !canContinue()) {
      stopped = true;
      return false;
    }
    let result;
    try {
      result = lab.trial({ x: candidate.slice() });
    } catch (e) {
      stopped = true;
      return false;
    }
    evaluations++;
    const fit = scoreResult(result);
    if (fit > bestScore) {
      bestScore = fit;
      bestX = candidate.slice();
    }
    return fit;
  };

  for (let i = 0; i < seeds.length && evaluations < budget; i++) {
    if (evaluate(seeds[i]) === false && stopped) break;
  }

  if (evaluations < budget && !stopped) {
    const identity = () => {
      const a = new Array(n);
      for (let i = 0; i < n; i++) {
        a[i] = new Array(n).fill(0);
        a[i][i] = 1;
      }
      return a;
    };

    const eigen = matrix => {
      const a = new Array(n);
      const b = identity();
      for (let i = 0; i < n; i++) {
        a[i] = new Array(n);
        for (let j = 0; j < n; j++) {
          a[i][j] = 0.5 * (matrix[i][j] + matrix[j][i]);
        }
      }

      for (let iteration = 0; iteration < 8 * n * n; iteration++) {
        let p = 0;
        let q = 1;
        let largest = 0;
        for (let i = 0; i < n; i++) {
          for (let j = i + 1; j < n; j++) {
            const value = Math.abs(a[i][j]);
            if (value > largest) {
              largest = value;
              p = i;
              q = j;
            }
          }
        }
        if (largest < 1e-11) break;

        const app = a[p][p];
        const aqq = a[q][q];
        const apq = a[p][q];
        const tau = (aqq - app) / (2 * apq);
        const sign = tau >= 0 ? 1 : -1;
        const t = sign / (Math.abs(tau) + Math.sqrt(1 + tau * tau));
        const c = 1 / Math.sqrt(1 + t * t);
        const s = t * c;

        for (let k = 0; k < n; k++) {
          if (k !== p && k !== q) {
            const akp = a[k][p];
            const akq = a[k][q];
            a[k][p] = c * akp - s * akq;
            a[p][k] = a[k][p];
            a[k][q] = s * akp + c * akq;
            a[q][k] = a[k][q];
          }
          const bkp = b[k][p];
          const bkq = b[k][q];
          b[k][p] = c * bkp - s * bkq;
          b[k][q] = s * bkp + c * bkq;
        }
        a[p][p] = app - t * apq;
        a[q][q] = aqq + t * apq;
        a[p][q] = 0;
        a[q][p] = 0;
      }

      const d = new Array(n);
      for (let i = 0; i < n; i++) d[i] = Math.sqrt(Math.max(1e-8, a[i][i]));
      return { b: b, d: d };
    };

    const inverseSqrtTimes = (v, e) => {
      const tmp = new Array(n).fill(0);
      const out = new Array(n).fill(0);
      for (let j = 0; j < n; j++) {
        for (let i = 0; i < n; i++) tmp[j] += e.b[i][j] * v[i];
        tmp[j] /= e.d[j];
      }
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) out[i] += e.b[i][j] * tmp[j];
      }
      return out;
    };

    const normal = () => {
      const u = Math.max(1e-12, Math.random());
      const v = Math.random();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };

    const lambda = 10;
    const mu = 5;
    const muWeights = new Array(mu);
    let weightSum = 0;
    for (let i = 0; i < mu; i++) {
      muWeights[i] = Math.log(mu + 0.5) - Math.log(i + 1);
      weightSum += muWeights[i];
    }
    for (let i = 0; i < mu; i++) muWeights[i] /= weightSum;

    let squaredWeightSum = 0;
    for (let i = 0; i < mu; i++) squaredWeightSum += muWeights[i] * muWeights[i];
    const muEff = 1 / squaredWeightSum;

    const cSigma = (muEff + 2) / (n + muEff + 5);
    const cC = (4 + muEff / n) / (n + 4 + 2 * muEff / n);
    const c1 = 2 / (Math.pow(n + 1.3, 2) + muEff);
    const cMu = Math.max(
      0,
      Math.min(
        1 - c1,
        2 * (muEff - 2 + 1 / muEff) / (Math.pow(n + 2, 2) + muEff)
      )
    );
    const damping = 1 + 2 * Math.max(
      0,
      Math.sqrt((muEff - 1) / (n + 1)) - 1
    ) + cSigma;
    const chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));

    let mean = bestX.slice();
    let covariance = identity();
    let sigma = 0.38;
    let pathSigma = new Array(n).fill(0);
    let pathC = new Array(n).fill(0);
    let generation = 0;

    while (evaluations < budget && !stopped && canContinue()) {
      const eig = eigen(covariance);
      const population = [];
      const count = Math.min(lambda, budget - evaluations);

      for (let k = 0; k < count; k++) {
        if (!canContinue()) {
          stopped = true;
          break;
        }

        let candidate;
        if (k === 0) {
          candidate = mean.slice();
        } else {
          const scaled = new Array(n);
          for (let j = 0; j < n; j++) scaled[j] = eig.d[j] * normal();
          candidate = new Array(n).fill(0);
          for (let i = 0; i < n; i++) {
            let step = 0;
            for (let j = 0; j < n; j++) step += eig.b[i][j] * scaled[j];
            candidate[i] = clamp(mean[i] + sigma * step, -1, 1);
          }
        }

        const fit = evaluate(candidate);
        if (fit === false && stopped) break;
        population.push({ x: candidate.slice(), fit: fit });
      }

      if (stopped || population.length < mu) break;
      population.sort((a, b) => b.fit - a.fit);

      const oldMean = mean.slice();
      const newMean = new Array(n).fill(0);
      for (let k = 0; k < mu; k++) {
        for (let i = 0; i < n; i++) newMean[i] += muWeights[k] * population[k].x[i];
      }
      mean = newMean.map(v => clamp(v, -1, 1));

      const yMean = new Array(n);
      for (let i = 0; i < n; i++) yMean[i] = (mean[i] - oldMean[i]) / sigma;
      const whitened = inverseSqrtTimes(yMean, eig);
      for (let i = 0; i < n; i++) {
        pathSigma[i] = (1 - cSigma) * pathSigma[i] +
          Math.sqrt(cSigma * (2 - cSigma) * muEff) * whitened[i];
      }

      let pathNorm = 0;
      for (let i = 0; i < n; i++) pathNorm += pathSigma[i] * pathSigma[i];
      pathNorm = Math.sqrt(pathNorm);
      generation++;
      const normalization = Math.sqrt(1 - Math.pow(1 - cSigma, 2 * generation));
      const hsig = pathNorm / Math.max(1e-12, normalization) / chiN <
        1.4 + 2 / (n + 1) ? 1 : 0;

      for (let i = 0; i < n; i++) {
        pathC[i] = (1 - cC) * pathC[i] +
          hsig * Math.sqrt(cC * (2 - cC) * muEff) * yMean[i];
      }

      const nextCovariance = new Array(n);
      for (let i = 0; i < n; i++) nextCovariance[i] = new Array(n).fill(0);
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
          let rankMu = 0;
          for (let k = 0; k < mu; k++) {
            const yi = (population[k].x[i] - oldMean[i]) / sigma;
            const yj = (population[k].x[j] - oldMean[j]) / sigma;
            rankMu += muWeights[k] * yi * yj;
          }
          nextCovariance[i][j] =
            (1 - c1 - cMu) * covariance[i][j] +
            c1 * (pathC[i] * pathC[j] +
              (1 - hsig) * cC * (2 - cC) * covariance[i][j]) +
            cMu * rankMu;
        }
      }
      for (let i = 0; i < n; i++) {
        nextCovariance[i][i] = Math.max(1e-8, nextCovariance[i][i]);
      }
      covariance = nextCovariance;

      sigma *= Math.exp((cSigma / damping) * (pathNorm / chiN - 1));
      sigma = clamp(sigma, 0.035, 0.85);
    }
  }

  if (!finite(bestScore) || bestScore < -100000) bestX = zero.slice();
  return { x: bestX };
}

function policy(obs, params, mem) {
  const PI = Math.PI;
  const TAU = 2 * PI;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const finite = v => typeof v === "number" && Number.isFinite(v);
  const read = (a, i, fallback) => {
    const v = a && a[i];
    return finite(v) ? v : fallback;
  };
  const mod = v => {
    v %= TAU;
    return v < 0 ? v + TAU : v;
  };
  const wrap = v => {
    v = mod(v + PI) - PI;
    return v;
  };

  if (!mem || typeof mem !== "object") mem = {};
  const x = params && Array.isArray(params.x)
    ? params.x
    : (Array.isArray(params) ? params : []);
  const gene = (i, center, scale) =>
    center + scale * clamp(finite(x[i]) ? x[i] : 0, -1, 1);

  const freq = clamp(gene(0, 1.0, 0.45), 0.55, 1.45);
  const hipAmp = clamp(gene(1, 0.26, 0.45), -0.22, 0.72);
  const hipBias = gene(2, 0, 0.10);
  const swingFrac = clamp(gene(3, 0.37, 0.08), 0.28, 0.48);
  const kneeAmp = clamp(gene(4, 0.60, 0.34), 0.20, 0.98);
  const kneeBase = clamp(gene(5, 0.035, 0.065), -0.035, 0.10);
  const ankleCouple = clamp(gene(6, 0.35, 0.90), -0.55, 1.25);
  const ankleSwing = gene(7, 0.10, 0.13);
  const armAmp = clamp(gene(8, 0.24, 0.24), 0, 0.50);
  const leanBase = clamp(gene(9, 0.03, 0.065), -0.08, 0.12);
  const hipP = clamp(gene(10, 0.90, 1.05), -0.15, 1.95);
  const hipD = clamp(gene(11, 0.18, 0.28), -0.10, 0.46);
  const waistP = clamp(gene(12, 1.35, 0.85), 0.50, 2.20);
  const waistD = clamp(gene(13, 0.30, 0.22), 0.08, 0.52);
  const rollP = clamp(gene(14, 1.05, 0.75), 0.30, 1.80);
  const rollD = clamp(gene(15, 0.18, 0.18), 0, 0.36);
  const outBias = clamp(gene(16, 0.06, 0.06), 0, 0.12);
  const phaseGene = clamp(finite(x[17]) ? x[17] : 0, -1, 1);
  const servoK = clamp(gene(18, 0.98, 0.32), 0.60, 1.35);
  const servoD = clamp(gene(19, 1.0, 0.42), 0.55, 1.50);
  const ankleP = gene(20, 0.05, 0.24);
  const ankleD = gene(21, 0.02, 0.14);
  const terrainLift = clamp(gene(22, 1.25, 0.85), 0.35, 2.15);
  const phaseLock = clamp(gene(23, 0.36, 0.29), 0.05, 0.66);
  const rampTime = clamp(gene(24, 0.35, 0.25), 0.10, 0.60);
  const hipCatch = gene(25, 0.42, 0.48);
  const lateralP = clamp(gene(26, 0.72, 0.55), 0.15, 1.27);
  const lateralD = clamp(gene(27, 0.12, 0.12), 0, 0.24);
  const yawP = clamp(gene(28, 0.25, 0.25), 0, 0.50);
  const yawD = clamp(gene(29, 0.07, 0.08), 0, 0.15);

  const filt = (key, value, alpha) => {
    if (!finite(mem[key])) mem[key] = value;
    else mem[key] += alpha * (value - mem[key]);
    return mem[key];
  };
  const filtAngle = (key, value, alpha) => {
    if (!finite(mem[key])) mem[key] = value;
    else mem[key] = wrap(mem[key] + alpha * wrap(value - mem[key]));
    return mem[key];
  };

  const now = obs && finite(obs.t) ? obs.t : 0;
  const orientation = obs && obs.orientation;
  const gyro = obs && obs.gyro;

  const roll = filt("_roll", read(orientation, 0, 0), 0.48);
  const pitch = filt("_pitch", read(orientation, 1, 0), 0.48);
  const yaw = filtAngle("_yaw", read(orientation, 2, 0), 0.34);
  const gx = filt("_gx", read(gyro, 0, 0), 0.62);
  const gy = filt("_gy", read(gyro, 1, 0), 0.62);
  const gz = filt("_gz", read(gyro, 2, 0), 0.58);

  const ground = obs && obs.ground;
  const gh = (row, col) => read(ground, 3 * row + col, 0);
  const distances = [0.3, 0.6, 1.0, 1.5, 2.0, 3.0];
  const weights = [1.45, 1.30, 1.05, 0.78, 0.50, 0.25];
  const centerHeights = new Array(6);
  let sumW = 0;
  let sumD = 0;
  let sumH = 0;
  for (let i = 0; i < 6; i++) {
    centerHeights[i] = gh(i, 1);
    sumW += weights[i];
    sumD += weights[i] * distances[i];
    sumH += weights[i] * centerHeights[i];
  }
  const meanD = sumD / Math.max(1e-8, sumW);
  const meanH = sumH / Math.max(1e-8, sumW);
  let slopeNum = 0;
  let slopeDen = 0;
  for (let i = 0; i < 6; i++) {
    const dx = distances[i] - meanD;
    slopeNum += weights[i] * dx * (centerHeights[i] - meanH);
    slopeDen += weights[i] * dx * dx;
  }
  const slope = clamp(slopeDen > 1e-8 ? slopeNum / slopeDen : 0, -0.65, 0.65);
  const terrainPitch = Math.atan(slope);
  const terrainRoll = Math.atan(clamp((gh(1, 0) - gh(1, 2)) / 0.8, -0.50, 0.50));
  const terrainLean = clamp(leanBase + 0.16 * terrainPitch, -0.16, 0.18);

  const pitchPred = pitch + 0.035 * gy;
  const rollPred = roll + 0.025 * gx;
  const pitchError = clamp(pitchPred - terrainLean, -1.0, 1.0);
  const rollError = clamp(rollPred - terrainRoll, -0.8, 0.8);

  const forces = obs && obs.feet;
  const forceL = filt("_forceL", Math.max(0, read(forces, 0, 0)), 0.40);
  const forceR = filt("_forceR", Math.max(0, read(forces, 1, 0)), 0.40);
  const threshold = Math.max(12, 0.13 * (forceL + forceR));
  const contactL = forceL > threshold;
  const contactR = forceR > threshold;

  const phaseStart = mod(TAU * (swingFrac + 0.5 * phaseGene));
  const rateBoost = clamp(1 + 0.24 * pitchError + 0.08 * gy, 0.68, 1.42);
  let phase;
  if (finite(mem._phase)) {
    const lastT = finite(mem._phaseT) ? mem._phaseT : now;
    const dt = clamp(now - lastT, 0, 0.08);
    phase = mod(mem._phase + TAU * freq * rateBoost * dt);
  } else {
    phase = phaseStart;
  }

  let airL = typeof mem._airL === "boolean" ? mem._airL : !contactL;
  let airR = typeof mem._airR === "boolean" ? mem._airR : !contactR;
  let airSinceL = finite(mem._airSinceL) ? mem._airSinceL : now;
  let airSinceR = finite(mem._airSinceR) ? mem._airSinceR : now;
  let landedL = false;
  let landedR = false;

  if (!contactL) {
    if (!airL) airSinceL = now;
    airL = true;
  } else {
    if (airL && now - airSinceL > 0.05) landedL = true;
    airL = false;
  }
  if (!contactR) {
    if (!airR) airSinceR = now;
    airR = true;
  } else {
    if (airR && now - airSinceR > 0.05) landedR = true;
    airR = false;
  }

  if (landedL && !landedR) {
    const target = TAU * swingFrac;
    phase = mod(phase + phaseLock * clamp(wrap(target - phase), -2.6, 2.6));
  } else if (landedR && !landedL) {
    const target = mod(PI + TAU * swingFrac);
    phase = mod(phase + phaseLock * clamp(wrap(target - phase), -2.6, 2.6));
  }

  mem._phase = phase;
  mem._phaseT = now;
  mem._airL = airL;
  mem._airR = airR;
  mem._airSinceL = airSinceL;
  mem._airSinceR = airSinceR;

  const legPattern = u => {
    if (u < swingFrac) {
      const r = clamp(u / swingFrac, 0, 1);
      return [
        -Math.cos(PI * r),
        Math.pow(Math.max(0, Math.sin(PI * r)), 0.80)
      ];
    }
    const r = clamp((u - swingFrac) / (1 - swingFrac), 0, 1);
    return [Math.cos(PI * r), 0];
  };

  const uL = phase / TAU;
  const uR = (uL + 0.5) % 1;
  const gaitL = legPattern(uL);
  const gaitR = legPattern(uR);

  const rampU = clamp(now / rampTime, 0, 1);
  const ramp = rampU * rampU * (3 - 2 * rampU);

  const hipCorrection = clamp(hipP * pitchError + hipD * gy, -0.55, 0.70);
  const catchStep = clamp(hipCatch * (pitchError + 0.08 * gy), -0.35, 0.55);
  const hipL = ramp * (hipBias + hipAmp * gaitL[0]) +
    hipCorrection + catchStep * gaitL[1];
  const hipR = ramp * (hipBias + hipAmp * gaitR[0]) +
    hipCorrection + catchStep * gaitR[1];

  const upL = Math.max(0, gh(0, 0), gh(0, 1), gh(1, 0), gh(1, 1));
  const upR = Math.max(0, gh(0, 1), gh(0, 2), gh(1, 1), gh(1, 2));
  const clearL = clamp(terrainLift * upL, 0, 0.55);
  const clearR = clamp(terrainLift * upR, 0, 0.55);

  const kneeL = clamp(
    kneeBase + ramp * ((kneeAmp + clearL + 0.12 * Math.max(0, pitchError)) * gaitL[1]),
    -0.04, 1.35
  );
  const kneeR = clamp(
    kneeBase + ramp * ((kneeAmp + clearR + 0.12 * Math.max(0, pitchError)) * gaitR[1]),
    -0.04, 1.35
  );

  const ankleBalance = clamp(ankleP * pitchError + ankleD * gy, -0.22, 0.22);
  const ankleL = ankleCouple * (hipL - kneeL) + ankleBalance +
    0.12 * terrainPitch + ramp * ankleSwing * gaitL[1];
  const ankleR = ankleCouple * (hipR - kneeR) + ankleBalance +
    0.12 * terrainPitch + ramp * ankleSwing * gaitR[1];

  const lateral = clamp(lateralP * rollError + lateralD * gx, -0.24, 0.24);
  const twist = clamp(0.015 - yawP * yaw - yawD * gz, -0.16, 0.16);
  const ankleRollL = 0.10 * terrainRoll - 0.035 * rollError;
  const ankleRollR = -0.10 * terrainRoll - 0.035 * rollError;

  const targets = new Array(25).fill(0);
  targets[0] = clamp(-waistP * pitchError - waistD * gy, -0.42, 0.60);
  targets[1] = clamp(-rollP * rollError - rollD * gx, -0.38, 0.38);
  targets[2] = clamp(-yawP * yaw - yawD * gz, -0.30, 0.30);

  targets[3] = hipL;
  targets[4] = outBias - lateral;
  targets[5] = twist;
  targets[6] = kneeL;
  targets[7] = ankleL;
  targets[8] = ankleRollL;
  targets[9] = ramp * 0.10 * gaitL[1];

  targets[10] = -ramp * armAmp * gaitL[0];
  targets[11] = clamp(0.04 + 0.12 * rollError, -0.10, 0.25);
  targets[12] = 0;
  targets[13] = 0.16;

  targets[14] = hipR;
  targets[15] = outBias + lateral;
  targets[16] = twist;
  targets[17] = kneeR;
  targets[18] = ankleR;
  targets[19] = ankleRollR;
  targets[20] = ramp * 0.10 * gaitR[1];

  targets[21] = -ramp * armAmp * gaitR[0];
  targets[22] = clamp(0.04 - 0.12 * rollError, -0.10, 0.25);
  targets[23] = 0;
  targets[24] = 0.16;

  const lo = [
    -0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05,
    -0.748, -0.458, -0.392, -1.08, -0.183, -0.722, -0.05,
    -0.432, -0.265, -0.481, -0.05, -0.713, -0.375, -0.384,
    -1.149, -0.214, -0.775, -0.05
  ];
  const hi = [
    0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286,
    0.515, 0.359, 0.97, 2.326, 1.833, 0.807, 2.192,
    1.818, 0.542, 0.696, 2.167, 0.485, 0.356, 1.032,
    2.496, 1.823, 0.855, 2.289
  ];
  const kp = [
    4.0, 3.8, 2.4, 2.6, 2.8, 1.9, 4.0, 2.8, 2.8, 1.7,
    2.4, 2.2, 1.8, 2.0, 2.6, 2.8, 1.9, 4.0, 2.8, 2.8,
    1.7, 2.4, 2.2, 1.8, 2.0
  ];
  const kd = [
    0.27, 0.24, 0.18, 0.19, 0.18, 0.14, 0.25, 0.17, 0.17, 0.10,
    0.16, 0.16, 0.13, 0.14, 0.19, 0.18, 0.14, 0.25, 0.17, 0.17,
    0.10, 0.16, 0.16, 0.13, 0.14
  ];

  const joints = obs && obs.joints;
  const speeds = obs && obs.speeds;
  const commands = new Array(25);
  for (let i = 0; i < 25; i++) {
    const target = clamp(targets[i], lo[i] + 0.003, hi[i] - 0.003);
    const q = read(joints, i, 0);
    const v = read(speeds, i, 0);
    commands[i] = clamp(
      kp[i] * servoK * (target - q) - kd[i] * servoD * v,
      -1, 1
    );
  }
  return commands;
}

function learn(lab) {
  const finite = v => typeof v === "number" && Number.isFinite(v);
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const n = 30;
  const zero = new Array(n).fill(0);

  if (!lab || typeof lab.trial !== "function") return { x: zero };

  let budget = 200;
  try {
