    }

    const distance = finite(result.distance) ? result.distance : 0;
    const time = finite(result.time)
      ? clamp(result.time, 0, 10)
      : (result.outcome === "finished" ? 10 : 0);

    let score = distance + 0.075 * time;
    if (result.outcome === "finished") score += 0.40;

    const trace = result.trace;
    if (Array.isArray(trace) && trace.length) {
