  let stopped = false;
  let bestScore = -Infinity;
  let bestX = zero.slice();
  let archive = [];

  const wrapGene = v => {
    while (v > 1) v -= 2;
    while (v < -1) v += 2;
    return v;
  };
  const phaseDiff = (a, b) => {
