  const seeds = [];
  const addSeed = changes => seeds.push(make(changes));
  addSeed({});
  addSeed({ 0: -0.55, 1: -0.20, 3: -0.25, 4: -0.35, 6: 0.45, 10: 0.30, 12: 0.55, 13: 0.25 });
  addSeed({ 0: 0.40, 1: 0.35, 3: -0.15, 4: 0.25, 6: 0.45, 10: 0.40, 12: 0.25, 25: 0.40, 17: -0.45 });
  addSeed({ 0: -0.35, 1: -0.45, 4: -0.20, 6: -0.30, 12: 0.70, 13: 0.50, 17: 0.45 });
  addSeed({ 10: 0.75, 11: 0.20, 12: 0.75, 13: 0.35, 6: 0.45 });
  addSeed({ 10: -0.40, 12: 0.80, 13: 0.50, 14: 0.45, 19: 0.35 });
  addSeed({ 6: -0.80, 20: 0.20, 21: 0.15, 0: -0.20, 12: 0.45 });
  addSeed({ 6: -0.55, 20: -0.55, 21: -0.35, 0: 0.10, 12: 0.65 });
  addSeed({ 6: 0.60, 20: 0.65, 21: 0.40, 0: -0.20, 12: 0.45 });
  addSeed({ 1: -1.0, 0: -0.35, 4: -0.25, 10: 0.45, 12: 0.70, 17: 0.40 });
  addSeed({ 1: 0.45, 0: -0.30, 4: 0.25, 10: 0.40, 12: 0.45, 17: -0.45 });
  addSeed({ 17: -0.90, 0: -0.20, 6: 0.45 });
  addSeed({ 17: -0.50, 0: -0.30, 10: 0.35 });
  addSeed({ 17: 0.50, 0: -0.25, 12: 0.40 });
  addSeed({ 17: 0.90, 0: -0.15, 6: -0.40 });
  addSeed({ 3: -0.70, 4: 0.45, 22: 0.55, 0: -0.35, 12: 0.50 });
  addSeed({ 3: 0.70, 4: -0.30, 0: 0.10, 10: 0.45, 12: 0.50 });
  addSeed({ 18: -0.65, 19: 0.55, 0: -0.25, 12: 0.55, 6: 0.45 });
  addSeed({ 18: 0.45, 19: -0.25, 0: -0.40, 10: 0.30, 12: 0.35 });
  addSeed({ 14: 0.55, 15: 0.35, 26: 0.55, 27: 0.30, 17: 0.10 });
  addSeed({ 0: 0.55, 1: -0.25, 3: -0.25, 4: -0.30, 10: 0.35, 12: 0.60 });
  addSeed({ 0: -0.70, 1: 0.15, 3: 0.25, 4: 0.10, 10: 0.20, 12: 0.65 });
  addSeed({ 10: 0.50, 11: 0.60, 12: 0.40, 13: 0.55, 20: 0.45, 21: 0.50 });
  addSeed({ 16: 0.75, 26: 0.35, 27: 0.25, 0: -0.25, 12: 0.50 });
  addSeed({ 0: -0.40, 1: -0.10, 4: 0.50, 6: 0.50, 22: 0.80, 25: 0.45 });

