        : clamp(base[i] + delta, -1, 1);
      changed = true;
    }
    if (!changed) {
      const i = Math.floor(Math.random() * n);
      const delta = normal() * scales[i] * factor;
      a[i] = i === 17 ? wrapGene(base[i] + delta) : clamp(base[i] + delta, -1, 1);
    }
    return a;
  };

  let center = bestX.slice();
  let scales = new Array(n).fill(0.32);
  scales[17] = 0.28;
  let stagnant = 0;

