    const batch = [];
    const count = Math.min(8, budget - evaluations);

    for (let k = 0; k < count; k++) {
      if (!canContinue()) {
        stopped = true;
        break;
      }

      let base = center;
      let factor = 1;
      let sparse = 1;

      if (k % 4 === 0) {
        base = bestX;
        factor = 0.95;
        sparse = 1;
      } else if (k % 4 === 1) {
        base = center;
        factor = 1.0;
        sparse = 0.24;
      } else if (k % 4 === 2 && archive.length) {
        const pool = Math.min(6, archive.length);
        base = archive[Math.floor(Math.random() * pool)].x;
        factor = 1.20;
        sparse = 0.30;
      } else {
        base = center;
        factor = 1.35;
        sparse = 0.42;
      }

      const candidate = mutate(base, scales, factor, sparse);
      if (k === 7) {
        for (let j = 0; j < 3; j++) {
          const i = Math.floor(Math.random() * n);
          candidate[i] = i === 17
            ? wrapGene((Math.random() * 2) - 1)
            : (Math.random() * 2) - 1;
        }
      }

      const fit = evaluate(candidate);
      if (fit === null && stopped) break;
      batch.push({ x: candidate, fit: fit });
    }

    if (!batch.length) break;
    batch.sort((a, b) => b.fit - a.fit);

    const m = Math.min(3, batch.length);
    const weights = m === 1 ? [1] : (m === 2 ? [0.65, 0.35] : [0.55, 0.30, 0.15]);
    let weightSum = 0;
    for (let i = 0; i < m; i++) weightSum += weights[i];

    const mean = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      if (i === 17) {
        const anchor = batch[0].x[17];
        let deltaMean = 0;
        for (let k = 0; k < m; k++) {
          deltaMean += (weights[k] / weightSum) * phaseDiff(batch[k].x[17], anchor);
        }
        mean[i] = wrapGene(anchor + deltaMean);
      } else {
        for (let k = 0; k < m; k++) {
          mean[i] += (weights[k] / weightSum) * batch[k].x[i];
        }
        mean[i] = clamp(mean[i], -1, 1);
