    const blend = bestScore > beforeBest ? 0.78 : 0.58;
    for (let i = 0; i < n; i++) {
      const delta = i === 17
        ? phaseDiff(mean[i], center[i])
        : mean[i] - center[i];
      center[i] = i === 17
        ? wrapGene(center[i] + blend * delta)
        : clamp(center[i] + blend * delta, -1, 1);
    }

    for (let i = 0; i < n; i++) {
      let variance = 0;
      for (let k = 0; k < m; k++) {
        const d = i === 17
          ? phaseDiff(batch[k].x[i], mean[i])
          : batch[k].x[i] - mean[i];
        variance += (weights[k] / weightSum) * d * d;
      }
      const spread = Math.sqrt(Math.max(0, variance));
      const targetScale = clamp(0.08 + 1.45 * spread, 0.08, 0.50);
      scales[i] = clamp(0.72 * scales[i] + 0.28 * targetScale, 0.08, 0.50);
      if (bestScore > beforeBest) scales[i] = Math.max(0.09, 0.96 * scales[i]);
    }

    if (bestScore > beforeBest) {
      stagnant = 0;
    } else {
      stagnant++;
    }

    if (stagnant >= 5 && archive.length) {
      const pool = Math.min(6, archive.length);
      center = archive[Math.floor(Math.random() * pool)].x.slice();
      for (let i = 0; i < n; i++) {
        scales[i] = 0.20 + 0.12 * Math.random();
      }
      stagnant = 0;
    }
  }

