  const hipAmp = clamp(gene(1, 0.28, 0.23), 0.06, 0.54);
  const hipBias = gene(2, 0.015, 0.09);
  const swingFrac = clamp(gene(3, 0.39, 0.075), 0.30, 0.48);
  const kneeAmp = clamp(gene(4, 0.58, 0.30), 0.20, 0.95);
  const kneeBase = clamp(gene(5, 0.07, 0.055), 0.005, 0.15);
  const ankleCouple = clamp(gene(6, 0.30, 0.34), 0, 0.70);
  const armAmp = clamp(gene(7, 0.28, 0.25), 0, 0.55);
  const waistP = clamp(gene(8, 1.25, 0.65), 0.45, 2.0);
  const waistD = clamp(gene(9, 0.25, 0.18), 0.04, 0.52);
  const hipP = clamp(gene(10, 0.38, 0.55), 0, 1.0);
  const hipD = clamp(gene(11, 0.10, 0.18), 0, 0.32);
  const ankleP = clamp(gene(12, 0.12, 0.22), -0.10, 0.35);
  const rollP = clamp(gene(13, 1.0, 0.72), 0.30, 1.90);
  const rollD = clamp(gene(14, 0.20, 0.18), 0, 0.40);
  const outBias = clamp(gene(15, 0.14, 0.11), 0.02, 0.29);
  const phaseGene = clamp(finite(x[16]) ? x[16] : 0, -1, 1);
  const servoK = clamp(gene(17, 1.0, 0.28), 0.62, 1.38);
