        if (finite(p[3])) maxSide = Math.max(maxSide, Math.abs(p[3]));
        if (finite(p[4])) maxRoll = Math.max(maxRoll, Math.abs(p[4]));
        if (finite(p[5])) maxPitch = Math.max(maxPitch, Math.abs(p[5]));
