    }
    let sortedEst=archive.slice().filter(c=>c.valid).sort((a,b)=>estimateFrom(b.res,b.ana)-estimateFrom(a.res,a.ana));
    for(let i=0;i<Math.min(8,sortedEst.length);i++) addC(sortedEst[i]);
    let sortedW=archive.slice().filter(c=>c.valid).sort((a,b)=>b.walkScore-a.walkScore);
    for(let i=0;i<Math.min(5,sortedW.length);i++) addC(sortedW[i]);
    if(bestStand) addC(bestStand);
    if(bestWalk) addC(bestWalk);
    if(legacyC) addC(legacyC);

    function validate(c,maxExtra){
      const runs=[c];
      for(let r=0;r<maxExtra;r++){
        if(!canTry()) break;
        const c2=evalCand(c.mode,c.v,true);
        if(c2) runs.push(c2);
      }
      let validCount=0;
      let sumD=0,sumDFin=0,finCount=0;
      let minRatio=1,hRatioMin=1,maxSide=0,maxTilt=0;
      for(let r=0;r<runs.length;r++){
        const rr=runs[r];
        if(!rr||!rr.valid) continue;
        validCount++;
        let d=Number(rr.res.dis);
        d=Number(rr.res.distance);
        if(!isFinite(d)) d=0;
        sumD+=d;
        if(isFinished(rr.res)){ finCount++; sumDFin+=d; }
        if(rr.ana.minRatio<minRatio) minRatio=rr.ana.minRatio;
        if(rr.ana.hRatio<hRatioMin) hRatioMin=rr.ana.hRatio;
        const as=Math.abs(rr.ana.lastSide||0);
        if(as>maxSide) maxSide=as;
        if(rr.ana.finalTilt>maxTilt) maxTilt=rr.ana.finalTilt;
      }
      if(validCount===0) return {c:c,runs:runs,pred:-1e9};
      const avgD=sumD/validCount;
      let pred;
      if(finCount>0){
        const avgFin=sumDFin/finCount;
