        if(finCount<validCount) pred*=0.65;
      }else{
        pred=Math.max(0,avgD)*0.9;
      }
      pred-=2.5*Math.max(0,maxSide-0.25);
      pred-=4.0*Math.max(0,maxTilt-0.30);
      pred-=2.0*Math.max(0,0.72-minRatio);
      pred-=1.0*Math.max(0,0.80-hRatioMin);
      return {c:c,runs:runs,pred:pred,validCount:validCount,finCount:finCount,avgD:avgD,minRatio:minRatio,hRatioMin:hRatioMin,maxSide:maxSide,maxTilt:maxTilt};
    }

    let vals=[];
    let left=0;
    try{ if(lab.trialsLeft) left=lab.trialsLeft(); }catch(e){}
    for(let i=0;i<candList.length;i++){
      let c=candList[i];
      let maxExtra=0;
      try{ if(lab.trialsLeft) left=lab.trialsLeft(); }catch(e){ left=0; }
      if(left>15) maxExtra=(i<2?2:1);
      else if(left>5) maxExtra=(i<3?1:0);
      const val=validate(c,maxExtra);
      vals.push(val);
    }

    let chosen=null;
    let chosenPred=-1e9;
    for(let i=0;i<vals.length;i++){
      let val=vals[i];
      let p=val.pred;
      if(val.c.mode===0) p=Math.max(p,1.05);
      if(p>chosenPred){
        chosenPred=p;
        chosen=val.c;
      }
    }
    if(!chosen||chosenPred<1.02){
      return {mode:0,v:LEGACY_VEC.slice()};
    }
    return {mode:chosen.mode,v:chosen.v.slice()};
  }catch(e){
    if(bestEst&&bestEst.valid) return {mode:bestEst.mode,v:bestEst.v.slice()};
    if(bestWalk&&bestWalk.valid) return {mode:bestWalk.mode,v:bestWalk.v.slice()};
    if(bestStand&&bestStand.valid) return {mode:bestStand.mode,v:bestStand.v.slice()};
    return {mode:0,v:LEGACY_VEC.slice()};
  }
}

