    mem.yaw=Number(ori[2])||0;
    mem.rollRate=Number(gyr[0])||0;
    mem.pitchRate=Number(gyr[1])||0;
    mem.yawRate=Number(gyr[2])||0;
    mem.danger=0;
    mem.dqF=new Array(25).fill(0);
    mem.I=new Array(25).fill(0);
  }
  if(!mem.dqF) mem.dqF=new Array(25).fill(0);
  if(!mem.I) mem.I=new Array(25).fill(0);
  if(typeof mem.danger!=="number") mem.danger=0;
  let dt=t-mem.lastT;
  if(!(dt>0)||dt>0.2) dt=0.02;
  mem.lastT=t;
  const af=0.35;
  mem.roll=mem.roll*(1-af)+(Number(ori[0])||0)*af;
  mem.pitch=mem.pitch*(1-af)+(Number(ori[1])||0)*af;
  mem.yaw=mem.yaw*0.72+(Number(ori[2])||0)*0.28;
  mem.rollRate=mem.rollRate*0.72+(Number(gyr[0])||0)*0.28;
  mem.pitchRate=mem.pitchRate*0.72+(Number(gyr[1])||0)*0.28;
  mem.yawRate=mem.yawRate*0.72+(Number(gyr[2])||0)*0.28;
  const gr=obs.ground||[];
  function gv(i){ const v=gr[i]; return (typeof v==="number"&&isFinite(v))?v:0; }
  let hL=0,hR=0,hC=0,slope=0;
  if(gr.length>=18){
    hL=0.5*(gv(0)+gv(3));
    hR=0.5*(gv(2)+gv(5));
    hC=0.5*(gv(1)+gv(4));
    slope=(gv(7)-gv(1))/0.7;
  }else if(gr.length>=6){
    hL=0.5*(gv(0)+gv(3));
    hR=0.5*(gv(2)+gv(5));
    hC=0.5*(gv(1)+gv(4));
    slope=(gv(4)-gv(1))/0.7;
  }
  slope=Math.max(-0.6,Math.min(0.6,slope));
  const pr=ss(t/0.7);
  const start=gp(9);
  const rampT=Math.max(0.05,gp(10));
  let rampG=0;
  if(t>=start){
    let x=(t-start)/rampT;
    if(x<0)x=0; if(x>1)x=1;
    rampG=x*x*(3-2*x);
  }
  const lt=gp(72);
  let launchRamp=0;
  if(t>lt){
    let x=(t-lt)/Math.max(0.1,rampT);
    if(x<0)x=0; if(x>1)x=1;
    launchRamp=x*x*(3-2*x);
  }
  let gaitBase=gp(0)*rampG;
  let useLaunch=false;
  if(gaitBase<0.001 && launchRamp>0){
    gaitBase=gp(73)*launchRamp;
    useLaunch=true;
  }
  const effStart=useLaunch?lt:start;
  const freq=Math.max(0.2,Math.min(4.0,gp(1)));
  const phase=2*Math.PI*freq*Math.max(0,t-effStart);
  let pitchDes=gp(24)*pr+gp(25)*slope*pr+gp(71)*gaitBase+gp(74)*launchRamp;
  const eP=mem.pitch-pitchDes;
  const eR=mem.roll;
  const eYaw=mem.yaw;
  const thr=Math.max(0.05,gp(63));
  const rateThr=Math.max(0.2,gp(64));
  const sev=Math.max(Math.abs(eP)/thr,Math.abs(eR)/thr,Math.abs(mem.pitchRate)/rateThr,Math.abs(mem.rollRate)/rateThr);
  if(sev>1) mem.danger+=(sev-1)*gp(65)*dt;
  else mem.danger-=gp(66)*dt;
  if(mem.danger<0) mem.danger=0;
  if(mem.danger>1) mem.danger=1;
  const rec=mem.danger;
  const safety=Math.max(0,1-mem.danger);
  const g=gaitBase*safety;
  const hipC=gp(28)*eP+gp(29)*mem.pitchRate;
  const kneeC=gp(32)*eP+gp(33)*mem.pitchRate;
  const ankleC=gp(26)*eP+gp(27)*mem.pitchRate;
  const waistPC=gp(30)*eP+gp(31)*mem.pitchRate;
  const outC=gp(34)*eR+gp(35)*mem.rollRate;
  const ankleRC=gp(36)*eR+gp(37)*mem.rollRate;
  const waistRC=gp(38)*eR+gp(39)*mem.rollRate;
  const yawC=gp(40)*eYaw+gp(41)*mem.yawRate;
  const twistC=gp(42)*eYaw+gp(43)*mem.yawRate;
  let h0=gp(11)*pr+gp(70)*slope*pr;
  let k0=gp(12)*pr;
  let a0=gp(13)*pr+gp(69)*slope*pr;
  let o0=gp(14)*pr;
  let ar0=gp(15)*pr;
  let tw0=gp(16)*pr;
  let wp0=gp(17)*pr;
  let wr0=gp(18)*pr;
  let wy0=gp(19)*pr;
  let so0=gp(20)*pr;
  let sf0=gp(21)*pr;
  let el0=gp(22)*pr;
  let to0=gp(23)*pr;
  const qd=new Array(25).fill(0);
  qd[0]=wp0+waistPC;
  qd[1]=wr0+waistRC;
  qd[2]=wy0+yawC;
  const armPitch=gp(68)*eP;
  const armRoll=gp(67)*eR;
  const armSwing=gp(7)*Math.sin(phase)*g;
  qd[10]=sf0+armPitch-armSwing;
  qd[21]=sf0+armPitch+armSwing;
  qd[11]=so0+armRoll;
  qd[22]=so0-armRoll;
  qd[12]=0;
  qd[23]=0;
  qd[13]=el0;
  qd[24]=el0;
  for(let leg=0;leg<2;leg++){
    const isL=(leg===0);
    const theta=phase+(isL?0:gp(2));
    const sH=Math.sin(theta+gp(75));
    const cK=Math.cos(theta+gp(76));
    let lift=Math.max(0,cK);
    lift=lift*lift*(3-2*lift);
    const sA=Math.sin(theta+gp(77));
    const cO=Math.cos(theta+gp(78));
    const push=Math.max(0,-sA);
    const sideH=isL?hL:hR;
    const terrUp=Math.max(0,sideH-hC);
    let hip=h0+hipC+gp(3)*sH*g;
    hip+=rec*gp(61)*0.5;
    let knee=k0+kneeC+gp(4)*lift*g+gp(80)*terrUp*(0.3+lift)*Math.max(g,0.05);
    knee+=rec*gp(61);
    let ankle=a0+ankleC+gp(5)*sA*g+gp(81)*terrUp*0.5*Math.max(g,0.05);
    ankle-=rec*gp(61)*0.4;
    let toe=to0+gp(8)*push*g;
    let outDiff=(isL?-1:1)*outC;
    let gaitOut=(isL?1:-1)*gp(6)*cO*g;
    let out=o0+rec*gp(62)+outDiff+gaitOut;
    let aRoll=ar0+(isL?1:-1)*ankleRC+(isL?1:-1)*gp(6)*0.4*cO*g;
    let twist=tw0+twistC;
    if(isL){
      qd[3]=hip; qd[4]=out; qd[5]=twist; qd[6]=knee; qd[7]=ankle; qd[8]=aRoll; qd[9]=toe;
    }else{
      qd[14]=hip; qd[15]=out; qd[16]=twist; qd[17]=knee; qd[18]=ankle; qd[19]=aRoll; qd[20]=toe;
    }
  }
  for(let j=0;j<25;j++){
    if(!isFinite(qd[j])) qd[j]=0;
    if(qd[j]<LOJ[j]) qd[j]=LOJ[j];
    if(qd[j]>HIJ[j]) qd[j]=HIJ[j];
  }
  const kpH=gp(44),kdH=gp(45);
  const kpK=gp(46),kdK=gp(47);
  const kpA=gp(48),kdA=gp(49);
  const kpW=gp(50),kdW=gp(51);
  const kpArm=gp(52),kdArm=gp(53);
  const kpToe=gp(54),kdToe=gp(55);
  const ffH=gp(56),ffK=gp(57),ffA=gp(58),ffW=gp(59),ffArm=gp(60);
  const ki=gp(79);
  const cmd=new Array(25);
  for(let j=0;j<25;j++){
    let kp,kd,ff=0;
    if(j<3){ kp=kpW; kd=kdW; ff=ffW; }
    else if(j===6||j===17){ kp=kpK; kd=kdK; ff=ffK; }
    else if(j===9||j===20){ kp=kpToe; kd=kdToe; ff=ffA*0.3; }
    else if(j===7||j===8||j===18||j===19){ kp=kpA; kd=kdA; ff=ffA; }
    else if((j>=10&&j<=13)||(j>=21&&j<=24)){ kp=kpArm; kd=kdArm; ff=ffArm; }
    else { kp=kpH; kd=kdH; ff=ffH; }
    const qq=(typeof q[j]==="number"&&isFinite(q[j]))?q[j]:0;
    const rawSp=(typeof dq[j]==="number"&&isFinite(dq[j]))?dq[j]:0;
    const spF=(mem.dqF[j]||0)*0.75+rawSp*0.25;
    mem.dqF[j]=spF;
    let err=qd[j]-qq;
    let u=kp*err-kd*spF+ff+(mem.I[j]||0);
    let sat=false;
    if(u>1){u=1;sat=true;}
    if(u<-1){u=-1;sat=true;}
    if(!isFinite(u)){u=0;sat=false;}
    if(ki>0&&t>0.2&&Math.abs(err)<0.7){
      const add=ki*err*dt;
      if(!sat||err*u<0) mem.I[j]=(mem.I[j]||0)+add;
    }
    mem.I[j]=(mem.I[j]||0)*0.9995;
    if(mem.I[j]>0.25) mem.I[j]=0.25;
    if(mem.I[j]<-0.25) mem.I[j]=-0.25;
    cmd[j]=u;
  }
  return cmd;
}

function policy(obs,params,mem){
  let mode=1;
  let v=null;
  if(Array.isArray(params)){ v=params; mode=1; }
  else if(params&&typeof params==="object"){
    if(typeof params.m==="number") mode=params.m;
    else if(params.mode!==undefined) mode=params.mode;
    if(Array.isArray(params.v)) v=params.v;
  }
  if(mode===0) return legacyRun(obs,v,mem);
  return newRun(obs,v,mem);
}

function learn(lab){
  const N=NB;
  let trialCount=0;
  let cache={};
  let archive=[];
  let legacyBest=null;
  let bestStand=null;
  let bestWalk=null;
  let bestFall=null;
  let bestFallScore=-1e12;
  let template=null;
  let templateD=-1e12;
  let spare=null;

  function randn(){
    if(spare!==null){ const s=spare; spare=null; return s; }
    let u=0,v=0;
    while(u===0)u=Math.random();
    while(v===0)v=Math.random();
    const r=Math.sqrt(-2*Math.log(u));
    const a=2*Math.PI*v;
    spare=r*Math.sin(a);
    return r*Math.cos(a);
  }
  function clampV(v){
    const a=new Array(N);
    for(let i=0;i<N;i++){
      let x=(v&&i<v.length)?Number(v[i]):NaN;
      if(!isFinite(x)) x=NEW_BASE[i];
      if(!isFinite(x)) x=0;
      if(x<NEW_LO[i]) x=NEW_LO[i];
      if(x>NEW_HI[i]) x=NEW_HI[i];
      a[i]=x;
