    let d=Number(res.distance); if(!isFinite(d)) d=0;
    let sc=fin?6000:0;
    sc+=160*Math.min(t,10);
    if(!fin) sc-=650*Math.max(0,10-t);
    sc-=2200*Math.max(0,0.74-ana.minRatio);
    sc-=1000*Math.max(0,0.86-ana.lastRatio);
    sc-=240*Math.max(0,ana.avgTilt-0.14);
