    baseWalk=bestWalk?bestWalk.v:baseWalk;
    left=leftTrials();
    let w3=Math.min(14,Math.max(0,left-4));
    if(w3>0&&canTry()){
      const r=runES(baseWalk,walkActive2,w3,"walk",0.10,5);
