      return {m:1,v:clampV(v)};
    }
    if(bestWalk&&bestWalk.valid&&bestWalk.dist>0.20){
      let est=bestWalk.dist+0.10*Math.min(bestWalk.time,10);
      let le=-1e12;
      if(legacyBest&&legacyBest.valid) le=legacyBest.dist+0.10*Math.min(legacyBest.time,10);
      if(le>est) return {m:0,v:LEGACY_V.slice()};
      const v=bestWalk.v.slice(0,N);
      v[72]=100; v[73]=0;
      return {m:1,v:clampV(v)};
    }
    if(bestFall&&bestFall.valid){
      let est=bestFall.dist+0.10*Math.min(bestFall.time,10);
      let le=-1e12;
      if(legacyBest&&legacyBest.valid) le=legacyBest.dist+0.10*Math.min(legacyBest.time,10);
      if(le>est) return {m:0,v:LEGACY_V.slice()};
      if(bestFall.kind==="legacy") return {m:0,v:LEGACY_V.slice()};
      const v=bestFall.v.slice(0,N);
      if(v[72]>18) v[72]=100;
      return {m:1,v:clampV(v)};
    }
    if(legacyBest&&legacyBest.valid) return {m:0,v:LEGACY_V.slice()};
    if(bestWalk&&bestWalk.valid) return {m:1,v:clampV(bestWalk.v)};
    if(bestStand&&bestStand.valid) return {m:1,v:clampV(bestStand.v)};
    return {m:1,v:clampV(NEW_BASE)};
  }catch(e){
    if(bestStand&&bestStand.valid) return {m:1,v:clampV(bestStand.v)};
    if(bestWalk&&bestWalk.valid) return {m:1,v:clampV(bestWalk.v)};
    if(legacyBest&&legacyBest.valid) return {m:0,v:LEGACY_V.slice()};
    return {m:1,v:clampV(NEW_BASE)};
  }
}

// ---------- body data (motor order) ----------
var RW_JLO = [-0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05, -0.748, -0.458, -0.392,
  -1.08, -0.183, -0.722, -0.05, -0.432, -0.265, -0.481, -0.05, -0.713, -0.375,
  -0.384, -1.149, -0.214, -0.775, -0.05];
var RW_JHI = [0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286, 0.515, 0.359, 0.97,
  2.326, 1.833, 0.807, 2.192, 1.818, 0.542, 0.696, 2.167, 0.485, 0.356,
  1.032, 2.496, 1.823, 0.855, 2.289];

// Defaults: gait shape, sign-derived balance reflexes, PD gains.
// Pitch: waist, hip flex and ankle pitch all push the torso forward when commanded positive,
// so their feedback is negative. Roll: left hip-out/ankle-roll positive, right negative,
// waist roll negative. Yaw: waist yaw negative.
var RW_DEF = {
  f: 1.0, hipAmp: 0.35, hipBase: 0.05, kneeAmp: 0.6, kneeBase: 0.25, kneePh: 0.0,
  ankFlat: 1.0, ankBase: 0.0, pushAmp: 0.2, hipOut: 0.05, armAmp: 0.3, elbow: 0.5,
  sway: 0.0, waistBase: 0.1,
  kHP: -0.3, kAP: -0.3, kWP: -0.5, kD: 0.1,
  kRH: 0.3, kRA: 0.3, kRW: -0.5, kY: -0.3,
  kpLeg: 5.0, kpWaist: 4.0, kd: 0.08
};

function rw_num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function rw_clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
function rw_zeros() {
  var a = [];
  for (var i = 0; i < 25; i++) a.push(0);
  return a;
}

// One leg's targets. phL = leg phase, side = +1 left / -1 right.
function rw_leg(p, phL, ramp, side, cp, cr) {
  var s = Math.sin(phL);
  var hipG = p.hipBase + ramp * p.hipAmp * s;
  var knee = p.kneeBase + ramp * p.kneeAmp * Math.max(0, Math.cos(phL - p.kneePh));
  var push = ramp * p.pushAmp * Math.max(0, Math.cos(phL - 1.3 * Math.PI));
  return {
    hip: hipG + p.kHP * cp,
    hout: p.hipOut + side * p.kRH * cr,
    knee: knee,
    ankle: p.ankBase + p.ankFlat * (knee - hipG) - push + p.kAP * cp,
    aroll: side * p.kRA * cr
  };
}

function policy(obs, params, mem) {
  try {
    if (!obs || typeof obs !== 'object') return rw_zeros();
    if (!mem || typeof mem !== 'object') mem = {};

    var p = {};
    var key;
    for (key in RW_DEF) {
      if (RW_DEF.hasOwnProperty(key)) p[key] = RW_DEF[key];
    }
    if (params && typeof params === 'object') {
      for (key in RW_DEF) {
        if (RW_DEF.hasOwnProperty(key) && typeof params[key] === 'number' && isFinite(params[key])) {
          p[key] = params[key];
        }
      }
    }

    var t = rw_num(obs.t, 0);
    var ori = obs.orientation || [0, 0, 0];
    var roll = rw_num(ori[0], 0);
    var pitch = rw_num(ori[1], 0);
    var yaw = rw_num(ori[2], 0);
    var gyr = obs.gyro || [0, 0, 0];
    var gx = rw_num(gyr[0], 0);
    var gy = rw_num(gyr[1], 0);
    var q = obs.joints || [];
    var qd = obs.speeds || [];

    if (!mem.init) {
      mem.init = true;
      mem.phase = 0;
      mem.pf = pitch;
      mem.rf = roll;
      mem.yf = yaw;
      mem.pPrev = pitch;
      mem.rPrev = roll;
      mem.cP = 0;
      mem.cR = 0;
      mem.prate = 0;
      mem.rrate = 0;
      mem.lastT = t;
    } else {
      var dt = t - mem.lastT;
      if (!(dt > 0.001)) dt = 0.02;
      if (dt > 0.1) dt = 0.1;
      mem.lastT = t;
      var dP = pitch - mem.pPrev;
      var dR = roll - mem.rPrev;
      // learn whether the gyro axis agrees with the orientation derivative (sign of rate)
      mem.cP = 0.98 * mem.cP + dP * gy;
      mem.cR = 0.98 * mem.cR + dR * gx;
      var sP = mem.cP >= 0 ? 1 : -1;
      var sR = mem.cR >= 0 ? 1 : -1;
      mem.prate = 0.5 * mem.prate + 0.5 * sP * gy;
      mem.rrate = 0.5 * mem.rrate + 0.5 * sR * gx;
      mem.pf = 0.5 * mem.pf + 0.5 * pitch;
      mem.rf = 0.5 * mem.rf + 0.5 * roll;
      mem.yf = 0.8 * mem.yf + 0.2 * yaw;
      mem.phase = (mem.phase + 2 * Math.PI * p.f * dt) % (2 * Math.PI);
      mem.pPrev = pitch;
      mem.rPrev = roll;
    }

    var cp = mem.pf + p.kD * mem.prate;
    var cr = mem.rf + p.kD * mem.rrate;
    var ramp = rw_clamp(t / 1.5, 0, 1);
    var ph = mem.phase;
    var L = rw_leg(p, ph, ramp, 1, cp, cr);
    var R = rw_leg(p, ph + Math.PI, ramp, -1, cp, cr);
    var sL = Math.sin(ph);

    // targets in motor order
    var tgt = [
      p.waistBase + p.kWP * cp,                 // 0 waist_pitch
      ramp * p.sway * Math.cos(ph) + p.kRW * cr, // 1 waist_roll
      p.kY * mem.yf,                            // 2 waist_yaw
      L.hip, L.hout, 0, L.knee, L.ankle, L.aroll, 0,       // 3-9 left leg
      -ramp * p.armAmp * sL, 0.1, 0, p.elbow,              // 10-13 left arm
      R.hip, R.hout, 0, R.knee, R.ankle, R.aroll, 0,       // 14-20 right leg
      ramp * p.armAmp * sL, 0.1, 0, p.elbow                // 21-24 right arm
    ];

    var out = [];
    for (var i = 0; i < 25; i++) {
      var tg = rw_clamp(rw_num(tgt[i], 0), RW_JLO[i] + 0.02, RW_JHI[i] - 0.02);
      var isLeg = (i >= 3 && i <= 9) || (i >= 14 && i <= 20);
      var kp = isLeg ? p.kpLeg : p.kpWaist;
      var qi = rw_num(q[i], 0);
      var qdi = rw_num(qd[i], 0);
      out.push(rw_clamp(rw_num(kp * (tg - qi) - p.kd * qdi, 0), -1, 1));
    }
    return out;
  } catch (e) {
    return rw_zeros();
  }
}

function learn(lab) {
  var SPEC = [
    ['f', 0.6, 2.0, 1.0],
    ['hipAmp', 0.1, 0.6, 0.35],
    ['hipBase', -0.2, 0.4, 0.05],
    ['kneeAmp', 0.2, 1.2, 0.6],
    ['kneeBase', 0.05, 0.6, 0.25],
    ['kneePh', -0.6, 0.6, 0.0],
    ['ankFlat', 0.0, 1.3, 1.0],
    ['ankBase', -0.3, 0.3, 0.0],
    ['pushAmp', 0.0, 0.5, 0.2],
    ['hipOut', 0.0, 0.2, 0.05],
    ['armAmp', 0.0, 0.6, 0.3],
    ['elbow', 0.1, 1.2, 0.5],
    ['sway', -0.2, 0.2, 0.0],
    ['waistBase', -0.1, 0.5, 0.1],
    ['kHP', -1.0, 1.0, -0.3],
    ['kAP', -1.0, 1.0, -0.3],
    ['kWP', -1.2, 1.2, -0.5],
    ['kD', 0.0, 0.3, 0.1],
    ['kRH', -1.0, 1.0, 0.3],
    ['kRA', -1.0, 1.0, 0.3],
    ['kRW', -1.2, 1.2, -0.5],
    ['kY', -1.0, 1.0, -0.3],
    ['kpLeg', 1.5, 12.0, 5.0],
    ['kpWaist', 1.5, 12.0, 4.0],
    ['kd', 0.0, 0.3, 0.08]
  ];
  var n = SPEC.length;
  var i, j, k, a;
  var archive = [];
  var RESERVE = 4; // trials kept back for final re-validation

  function clamp01(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }

  function toParams(u) {
    var o = {};
    for (var q = 0; q < n; q++) {
      o[SPEC[q][0]] = SPEC[q][1] + clamp01(u[q]) * (SPEC[q][2] - SPEC[q][1]);
    }
    return o;
  }

  function fitnessOf(r) {
    if (!r || typeof r !== 'object') return -100;
    if (r.outcome !== 'finished' && r.outcome !== 'fell') return -100;
    var d = Number(r.distance);
    if (!isFinite(d)) return -100;
    var tm = Number(r.time);
    if (!isFinite(tm)) tm = 0;
    if (tm < 0) tm = 0;
    if (tm > 10) tm = 10;
    var f = d + 0.2 * tm;
    var mx = 0;
    var tr = r.trace || [];
    for (var z = 0; z < tr.length; z++) {
      var row = tr[z];
      if (row && row.length >= 6) {
        var ar = Math.abs(Number(row[4]));
        var ap = Math.abs(Number(row[5]));
        if (isFinite(ar) && ar > mx) mx = ar;
        if (isFinite(ap) && ap > mx) mx = ap;
      }
    }
    if (mx > 0.5) f -= 2 * (mx - 0.5);
    return f;
  }

  function budgetOk(reserve) {
    var tl = (typeof lab.trialsLeft === 'function') ? Number(lab.trialsLeft()) : 200 - archive.length;
    var sl = (typeof lab.timeLeft === 'function') ? Number(lab.timeLeft()) : 1e9;
    if (!isFinite(tl)) tl = 0;
    if (!isFinite(sl)) sl = 0;
    return tl > reserve && sl > 2.0;
  }

  function evaluate(u, reserve) {
    if (!budgetOk(reserve)) return null;
    var uc = [];
    for (var q = 0; q < n; q++) uc.push(clamp01(u[q]));
    var prm = toParams(uc);
    var r = null;
    try { r = lab.trial(prm); } catch (e) { return null; }
    var rec = { u: uc, prm: prm, f: fitnessOf(r) };
    archive.push(rec);
    return rec;
  }

  function gauss() {
    var u1 = Math.random(), u2 = Math.random();
    if (u1 < 1e-12) u1 = 1e-12;
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }

  // start point: physics-informed defaults, in normalised [0,1] coordinates
  var u0 = [];
  for (i = 0; i < n; i++) u0.push((SPEC[i][3] - SPEC[i][1]) / (SPEC[i][2] - SPEC[i][1]));
  var fallback = toParams(u0);
  evaluate(u0, RESERVE);

  // separable CMA-ES
  var lambda = 4 + Math.floor(3 * Math.log(n));
  var mu = Math.floor(lambda / 2);
  var w = [], sumw = 0;
  for (i = 0; i < mu; i++) { w.push(Math.log(mu + 0.5) - Math.log(i + 1)); sumw += w[i]; }
  var sumw2 = 0;
  for (i = 0; i < mu; i++) { w[i] = w[i] / sumw; sumw2 += w[i] * w[i]; }
  var mueff = 1 / sumw2;
  var cs = (mueff + 2) / (n + mueff + 5);
  var ds = 1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (n + 1)) - 1) + cs;
  var cc = (4 + mueff / n) / (n + 4 + 2 * mueff / n);
  var sepf = (n + 2) / 3;
  var c1 = sepf * 2 / ((n + 1.3) * (n + 1.3) + mueff);
  var cmu = Math.min(1 - c1, sepf * 2 * (mueff - 2 + 1 / mueff) / ((n + 2) * (n + 2) + mueff));
  if (!(cmu > 0)) cmu = 0;
  var chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));

  var m = u0.slice();
  var sigma = 0.2;
  var Cd = [], Dv = [], pc = [], ps = [];
  function resetState() {
    Cd = []; Dv = []; pc = []; ps = [];
    for (var q = 0; q < n; q++) { Cd.push(1); Dv.push(1); pc.push(0); ps.push(0); }
  }
  resetState();

  var gen = 0;
  var go = true;
  while (go) {
    gen++;
    var pop = [];
    for (k = 0; k < lambda; k++) {
      var x = [];
      for (i = 0; i < n; i++) x.push(clamp01(m[i] + sigma * Dv[i] * gauss()));
      var rec = evaluate(x, RESERVE);
      if (!rec) { go = false; break; }
      pop.push(rec);
    }
    if (pop.length < mu) break;
    pop.sort(function (A, B) { return B.f - A.f; });

    var mOld = m.slice();
    var newM = [];
    for (i = 0; i < n; i++) {
      a = 0;
      for (j = 0; j < mu; j++) a += w[j] * pop[j].u[i];
      newM.push(a);
    }
    m = newM;

    var yw = [];
    for (i = 0; i < n; i++) yw.push((m[i] - mOld[i]) / sigma);
    var csF = Math.sqrt(cs * (2 - cs) * mueff);
    var psN2 = 0;
    for (i = 0; i < n; i++) {
      ps[i] = (1 - cs) * ps[i] + csF * yw[i] / Dv[i];
      psN2 += ps[i] * ps[i];
    }
    var hs = (psN2 / (1 - Math.pow(1 - cs, 2 * gen)) / n < 2 + 4 / (n + 1)) ? 1 : 0;
    var ccF = Math.sqrt(cc * (2 - cc) * mueff);
    for (i = 0; i < n; i++) pc[i] = (1 - cc) * pc[i] + hs * ccF * yw[i];
    for (i = 0; i < n; i++) {
      var rk = 0;
      for (j = 0; j < mu; j++) {
        var yi = (pop[j].u[i] - mOld[i]) / sigma;
        rk += w[j] * yi * yi;
      }
      var cnew = (1 - c1 - cmu) * Cd[i] + c1 * (pc[i] * pc[i] + (1 - hs) * cc * (2 - cc) * Cd[i]) + cmu * rk;
      Cd[i] = cnew > 1e-6 ? cnew : 1e-6;
      Dv[i] = Math.sqrt(Cd[i]);
    }
    sigma = sigma * Math.exp((cs / ds) * (Math.sqrt(psN2) / chiN - 1));
    if (sigma < 1e-4) sigma = 1e-4;
    if (sigma > 0.5) sigma = 0.5;

    // restart from the best point so far if the search has collapsed
    if (sigma < 0.01 && go) {
      var bestRec = null;
      for (i = 0; i < archive.length; i++) {
        if (!bestRec || archive[i].f > bestRec.f) bestRec = archive[i];
      }
      if (bestRec) m = bestRec.u.slice();
      sigma = 0.15;
      resetState();
      gen = 0;
    }
  }

  // final check: re-run the best few candidates once and keep the best average
  var ranked = archive.slice();
  ranked.sort(function (A, B) { return B.f - A.f; });
  var cands = [];
  for (i = 0; i < ranked.length && cands.length < 3; i++) {
    if (ranked[i].f > -50) cands.push(ranked[i]);
  }
  if (cands.length === 0) return fallback;

  var bestPrm = cands[0].prm;
  var bestScore = -Infinity;
  for (i = 0; i < cands.length; i++) {
    var sc = cands[i].f;
    if (budgetOk(0)) {
      var r2 = null;
      try { r2 = lab.trial(cands[i].prm); } catch (e) { r2 = null; }
      if (r2) sc = 0.5 * (cands[i].f + fitnessOf(r2));
    }
    if (sc > bestScore) { bestScore = sc; bestPrm = cands[i].prm; }
  }
  return bestPrm;
}

// ---------- body data (motor order, from the brief) ----------
var RW_LO = [-0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05, -0.748, -0.458, -0.392,
  -1.08, -0.183, -0.722, -0.05, -0.432, -0.265, -0.481, -0.05, -0.713, -0.375,
  -0.384, -1.149, -0.214, -0.775, -0.05];
var RW_HI = [0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286, 0.515, 0.359, 0.97,
  2.326, 1.833, 0.807, 2.192, 1.818, 0.542, 0.696, 2.167, 0.485, 0.356,
  1.032, 2.496, 1.823, 0.855, 2.289];

// Every parameter is a magnitude; each reflex sign follows from the joint conventions:
//  forward lean (pitch > 0): hip flex +kHP (pelvis moves back over the feet),
//                            ankle pitch -kAP (toes press down, centre of pressure forward),
//                            waist pitch -kWP (torso bends back)
//  right lean (roll > 0):    left hip-out -kRH (adduct), right hip-out +kRH (abduct),
//                            left ankle-roll +kRA, right ankle-roll -kRA, waist roll -kRW
//  left turn (yaw > 0):      left hip-twist -kY, right hip-twist +kY (toes turn right)
var RW_DEF = {
  f: 0.8, hipAmp: 0.16, hipBase: 0.0, beta: 0.6,
  kneeBase: 0.25, kneeAmp: 0.6, kneeAhead: 1.5, ankFlat: 0.8, ankPush: 0.2,
  lOff: -0.06, lAmp: 0.07, armAmp: 0.2,
  kHP: 0.4, kAP: 0.25, kWP: 0.3, kD: 0.08,
  kRH: 0.4, kRA: 0.25, kRW: 0.2, kDr: 0.08, kY: 0.15,
  kpLeg: 4.0, kpWaist: 4.0, kd: 0.1
};

// [name, low, high, default, log-scaled]
var RW_SPEC = [
  ['f', 0.4, 1.3, 0.8, false],
  ['hipAmp', 0.03, 0.4, 0.16, false],
  ['hipBase', -0.15, 0.15, 0.0, false],
  ['beta', 0.5, 0.8, 0.6, false],
  ['kneeBase', 0.05, 0.6, 0.25, false],
  ['kneeAmp', 0.1, 1.1, 0.6, false],
  ['kneeAhead', 0.0, 4.0, 1.5, false],
  ['ankFlat', 0.0, 1.2, 0.8, false],
  ['ankPush', 0.0, 0.6, 0.2, false],
  ['lOff', -0.25, 0.1, -0.06, false],
  ['lAmp', 0.0, 0.2, 0.07, false],
  ['armAmp', 0.0, 0.6, 0.2, false],
  ['kHP', 0.0, 1.0, 0.4, false],
  ['kAP', 0.0, 1.0, 0.25, false],
  ['kWP', 0.0, 1.5, 0.3, false],
  ['kD', 0.0, 0.3, 0.08, false],
  ['kRH', 0.0, 1.2, 0.4, false],
  ['kRA', 0.0, 1.0, 0.25, false],
  ['kRW', 0.0, 1.2, 0.2, false],
  ['kDr', 0.0, 0.3, 0.08, false],
  ['kY', 0.0, 0.8, 0.15, false],
  ['kpLeg', 1.5, 12.0, 4.0, true],
  ['kpWaist', 1.5, 12.0, 4.0, true],
  ['kd', 0.0, 0.4, 0.1, false]
];

function rwNum(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function rwClamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
function rwZeros() {
  var a = [];
  for (var i = 0; i < 25; i++) a.push(0);
  return a;
}

function rwParams(params) {
  var p = {};
  var k;
  for (k in RW_DEF) {
    if (RW_DEF.hasOwnProperty(k)) p[k] = RW_DEF[k];
  }
  if (params && typeof params === 'object') {
    for (k in RW_DEF) {
      if (RW_DEF.hasOwnProperty(k) && typeof params[k] === 'number' && isFinite(params[k])) {
        p[k] = params[k];
      }
    }
  }
  return p;
}

// Phase in [0, 2π) -> s in [0, 2): [0,1) is stance (foot planted), [1,2) is swing.
function rwPhaseS(ph, beta) {
  var TWO_PI = 2 * Math.PI;
  var b = TWO_PI * beta;
  if (ph < b) return ph / b;
  return 1 + (ph - b) / (TWO_PI - b);
}

// Raw targets for one leg (before PD). side: +1 left, -1 right.
function rwLeg(ph, side, p, ramp, cp, cr, yawF, gA) {
  var s = rwPhaseS(ph, p.beta);
  var c = Math.cos(Math.PI * s);
  var swing = (s >= 1) ? Math.sin(Math.PI * (s - 1)) : 0;
  var kAmp = p.kneeAmp + p.kneeAhead * (gA > 0 ? gA : 0);
  var flexTot = ramp * (p.hipBase + p.hipAmp * c) + p.kHP * cp;
  var knee = ramp * (p.kneeBase + kAmp * swing);
  var push = 0;
  if (s > 0.5 && s < 1.1) push = Math.sin(Math.PI * (s - 0.5) / 0.6);
  var ankle = p.ankFlat * (knee - flexTot) - ramp * p.ankPush * push - p.kAP * cp;
  return {
    flex: flexTot,
    knee: knee,
    ankle: ankle,
    hout: ramp * (p.lOff + p.lAmp * c) - side * p.kRH * cr,
    aroll: side * p.kRA * cr,
    twist: -side * p.kY * yawF,
    arm: -ramp * p.armAmp * c
  };
}

function policy(obs, params, mem) {
  try {
    if (!obs || typeof obs !== 'object') return rwZeros();
    if (!mem || typeof mem !== 'object') mem = {};
    var TWO_PI = 2 * Math.PI;
    var p = rwParams(params);
    p.f = rwClamp(p.f, 0.2, 2.0);
    p.beta = rwClamp(p.beta, 0.3, 0.95);

    var t = rwNum(obs.t, 0);
    var roll = 0, pitch = 0, yaw = 0;
    var ori = obs.orientation;
    if (ori && typeof ori.length === 'number' && ori.length >= 3) {
      roll = rwNum(ori[0], 0);
      pitch = rwNum(ori[1], 0);
      yaw = rwNum(ori[2], 0);
    }
    var gxr = 0, gyr = 0;
    var gyro = obs.gyro;
    if (gyro && typeof gyro.length === 'number' && gyro.length >= 2) {
      gxr = rwNum(gyro[0], 0);
      gyr = rwNum(gyro[1], 0);
    }
    var q = (obs.joints && typeof obs.joints.length === 'number') ? obs.joints : [];
    var qd = (obs.speeds && typeof obs.speeds.length === 'number') ? obs.speeds : [];
    var grd = (obs.ground && typeof obs.ground.length === 'number') ? obs.ground : [];

    if (!mem.init) {
      mem.init = true;
      mem.lastT = t;
      mem.phase = 0;
      mem.rollF = roll;
      mem.pitchF = pitch;
      mem.yawF = yaw;
      mem.rollRate = gxr;
      mem.pitchRate = gyr;
    } else {
      var dt = t - mem.lastT;
      if (!(dt > 0.001)) dt = 0.02;
      if (dt > 0.1) dt = 0.1;
      mem.lastT = t;
      mem.phase = (mem.phase + TWO_PI * p.f * dt) % TWO_PI;
      mem.rollF = 0.6 * mem.rollF + 0.4 * roll;
      mem.pitchF = 0.6 * mem.pitchF + 0.4 * pitch;
      mem.yawF = 0.7 * mem.yawF + 0.3 * yaw;
      mem.rollRate = 0.6 * mem.rollRate + 0.4 * gxr;
      mem.pitchRate = 0.6 * mem.pitchRate + 0.4 * gyr;
    }

    var ramp = rwClamp(t, 0, 1.0);
    var cp = mem.pitchF + p.kD * mem.pitchRate;
    var cr = mem.rollF + p.kDr * mem.rollRate;
    var g1 = (grd.length > 1) ? rwNum(grd[1], 0) : 0;
    var g4 = (grd.length > 4) ? rwNum(grd[4], 0) : 0;
    var gA = rwClamp(Math.max(g1, g4), 0, 0.4);

    var L = rwLeg(mem.phase, 1, p, ramp, cp, cr, mem.yawF, gA);
    var R = rwLeg((mem.phase + Math.PI) % TWO_PI, -1, p, ramp, cp, cr, mem.yawF, gA);

    var tgt = [
      -p.kWP * cp, -p.kRW * cr, 0,
      L.flex, L.hout, L.twist, L.knee, L.ankle, L.aroll, 0,
      L.arm, 0.1, 0, 0.3,
      R.flex, R.hout, R.twist, R.knee, R.ankle, R.aroll, 0,
      R.arm, 0.1, 0, 0.3
    ];

    var out = [];
    for (var i = 0; i < 25; i++) {
      var lo = RW_LO[i] + 0.02;
      var hi = RW_HI[i] - 0.02;
      var tg = rwClamp(rwNum(tgt[i], 0), lo, hi);
      var qi = rwNum(q[i], 0);
      var qdi = rwNum(qd[i], 0);
      var kp;
      if (i <= 2) kp = p.kpWaist;
      else if (i === 9 || i === 20) kp = 0.5 * p.kpLeg;
      else if ((i >= 3 && i <= 8) || (i >= 14 && i <= 19)) kp = p.kpLeg;
      else kp = 2.0;
      var u = kp * (tg - qi) - p.kd * qdi;
      if (!isFinite(u)) u = 0;
      out.push(rwClamp(u, -1, 1));
    }
    return out;
  } catch (e) {
    return rwZeros();
  }
}

function learn(lab) {
  var n = RW_SPEC.length;
  var RESERVE = 5;
  var archive = [];
  var best = null;
  var i, j, k, a;
  var mu = 1, w = [], mueff = 1, cs = 0.3, ds = 1, cc = 0.3, c1 = 0.01, cmu = 0.01, chiN = 1;
  var lambda = 4 + Math.floor(3 * Math.log(n));
  var Cd = [], Dv = [], pc = [], ps = [];

  function clamp01(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }

  function toParams(u) {
    var o = {};
    for (var q = 0; q < n; q++) {
      var sp = RW_SPEC[q];
      var v = clamp01(u[q]);
      if (sp[4]) {
        var la = Math.log(sp[1]);
        var lb = Math.log(sp[2]);
        o[sp[0]] = Math.exp(la + v * (lb - la));
      } else {
        o[sp[0]] = sp[1] + v * (sp[2] - sp[1]);
      }
    }
    return o;
  }

  function uFromParams(prm) {
    var u = [];
    for (var q = 0; q < n; q++) {
      var sp = RW_SPEC[q];
      var v = (prm && typeof prm[sp[0]] === 'number' && isFinite(prm[sp[0]])) ? prm[sp[0]] : sp[3];
      var uu;
      if (sp[4]) {
        uu = (Math.log(v) - Math.log(sp[1])) / (Math.log(sp[2]) - Math.log(sp[1]));
      } else {
        uu = (v - sp[1]) / (sp[2] - sp[1]);
      }
      if (!(uu === uu)) uu = 0.5;
      u.push(clamp01(uu));
    }
    return u;
  }

  function trialsLeft() {
    try {
      var v = (typeof lab.trialsLeft === 'function') ? Number(lab.trialsLeft()) : (200 - archive.length);
      return isFinite(v) ? v : 0;
    } catch (e) {
      return 0;
    }
  }

  function timeLeft() {
    try {
      var v = (typeof lab.timeLeft === 'function') ? Number(lab.timeLeft()) : 0;
      return isFinite(v) ? v : 0;
    } catch (e) {
      return 0;
    }
  }

  function fitnessOf(r) {
    if (!r || typeof r !== 'object') return -50;
    if (r.outcome !== 'finished' && r.outcome !== 'fell') return -50;
    var d = Number(r.distance);
    if (!isFinite(d)) return -50;
    var tm = Number(r.time);
    if (!isFinite(tm)) tm = 0;
    if (tm < 0) tm = 0;
    if (tm > 10) tm = 10;
    var f = 4 * d + 0.2 * tm + (r.outcome === 'finished' ? 0.5 : 0);
    var mt = 0, ms = 0;
    var tr = r.trace || [];
    for (var z = 0; z < tr.length; z++) {
      var row = tr[z];
      if (row && row.length >= 6) {
        var sd = Math.abs(Number(row[3]));
        var ro = Math.abs(Number(row[4]));
        var pt = Math.abs(Number(row[5]));
        if (isFinite(ro) && ro > mt) mt = ro;
        if (isFinite(pt) && pt > mt) mt = pt;
        if (isFinite(sd) && sd > ms) ms = sd;
      }
    }
    if (mt > 0.5) f -= 3 * (mt - 0.5);
    if (ms > 1.0) f -= 2 * (ms - 1.0);
    return f;
  }

  function evaluate(u, reserve) {
    if (trialsLeft() <= reserve) return null;
    if (timeLeft() < 2.5) return null;
    var uc = [];
    for (var q = 0; q < n; q++) uc.push(clamp01(u[q]));
    var prm = toParams(uc);
    var r = null;
    try {
      r = lab.trial(prm);
    } catch (e) {
      return null;
    }
    var dist = (r && typeof r === 'object') ? Number(r.distance) : 0;
    if (!isFinite(dist)) dist = 0;
    var rec = {
      u: uc,
      prm: prm,
      f: fitnessOf(r),
      dist: dist,
      outcome: (r && typeof r === 'object') ? String(r.outcome) : 'none'
    };
    archive.push(rec);
    if (!best || rec.f > best.f) best = rec;
    return rec;
  }

  function gauss() {
    var u1 = Math.random();
    var u2 = Math.random();
    if (u1 < 1e-12) u1 = 1e-12;
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }

  function setupWeights() {
    mu = Math.floor(lambda / 2);
    w = [];
    var sumw = 0;
    var q;
    for (q = 0; q < mu; q++) {
      w.push(Math.log(mu + 0.5) - Math.log(q + 1));
      sumw += w[q];
    }
    var sumw2 = 0;
    for (q = 0; q < mu; q++) {
      w[q] = w[q] / sumw;
      sumw2 += w[q] * w[q];
    }
    mueff = 1 / sumw2;
    cs = (mueff + 2) / (n + mueff + 5);
    ds = 1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (n + 1)) - 1) + cs;
    cc = (4 + mueff / n) / (n + 4 + 2 * mueff / n);
    var sepf = (n + 2) / 3;
    c1 = sepf * 2 / ((n + 1.3) * (n + 1.3) + mueff);
    cmu = Math.min(1 - c1, sepf * 2 * (mueff - 2 + 1 / mueff) / ((n + 2) * (n + 2) + mueff));
    if (!(cmu > 0)) cmu = 0;
    chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));
  }

  function resetState() {
    Cd = [];
    Dv = [];
    pc = [];
    ps = [];
    for (var q = 0; q < n; q++) {
      Cd.push(1);
      Dv.push(1);
      pc.push(0);
      ps.push(0);
    }
  }

  var result = null;
  try {
    var starts = [
      {},
      { f: 0.65, hipAmp: 0.12, kneeAmp: 0.7, kHP: 0.6, kAP: 0.35, kWP: 0.5, kRH: 0.6,
        kRA: 0.35, kRW: 0.3, kpLeg: 6, kpWaist: 6, kd: 0.15 },
      { f: 0.9, hipAmp: 0.2, kneeAmp: 0.5, kHP: 0.25, kAP: 0.15, kWP: 0.2, kRH: 0.25,
        kRA: 0.15, kRW: 0.1, kpLeg: 2.5, kpWaist: 3, kd: 0.08 }
    ];
    for (k = 0; k < starts.length; k++) evaluate(uFromParams(starts[k]), RESERVE);

    var m = (best ? best.u : uFromParams({})).slice();
    var sigma = 0.2;
    var gen = 0, stall = 0, bestGenF = -1e18;
    setupWeights();
    resetState();
    var go = true;
    while (go) {
      if (trialsLeft() <= RESERVE + 1 || timeLeft() < 4) break;
      if (gen >= 80 || archive.length > 260) break;
      gen++;
      var pop = [];
      for (k = 0; k < lambda; k++) {
        var x = [];
        for (i = 0; i < n; i++) x.push(clamp01(m[i] + sigma * Dv[i] * gauss()));
        var rec = evaluate(x, RESERVE);
        if (!rec) { go = false; break; }
        pop.push(rec);
      }
      if (pop.length < lambda) break;
      pop.sort(function (A, B) { return B.f - A.f; });

      var mOld = m.slice();
      var newM = [];
      for (i = 0; i < n; i++) {
        a = 0;
        for (j = 0; j < mu; j++) a += w[j] * pop[j].u[i];
        newM.push(clamp01(a));
      }
      m = newM;
      var yw = [];
      for (i = 0; i < n; i++) yw.push((m[i] - mOld[i]) / sigma);
      var csF = Math.sqrt(cs * (2 - cs) * mueff);
      var psN2 = 0;
      for (i = 0; i < n; i++) {
        ps[i] = (1 - cs) * ps[i] + csF * yw[i] / Dv[i];
        psN2 += ps[i] * ps[i];
      }
      var hs = ((psN2 / (1 - Math.pow(1 - cs, 2 * gen))) / n < 2 + 4 / (n + 1)) ? 1 : 0;
      var ccF = Math.sqrt(cc * (2 - cc) * mueff);
      for (i = 0; i < n; i++) pc[i] = (1 - cc) * pc[i] + hs * ccF * yw[i];
      for (i = 0; i < n; i++) {
        var rk = 0;
        for (j = 0; j < mu; j++) {
          var yi = (pop[j].u[i] - mOld[i]) / sigma;
          rk += w[j] * yi * yi;
        }
        var cnew = (1 - c1 - cmu) * Cd[i] + c1 * (pc[i] * pc[i] + (1 - hs) * cc * (2 - cc) * Cd[i]) + cmu * rk;
        if (!(cnew > 1e-8)) cnew = 1e-8;
        Cd[i] = cnew;
        Dv[i] = Math.sqrt(cnew);
      }
      sigma = sigma * Math.exp((cs / ds) * (Math.sqrt(psN2) / chiN - 1));
      if (sigma < 1e-3) sigma = 1e-3;
      if (sigma > 0.4) sigma = 0.4;

      if (pop[0].f > bestGenF + 1e-6) {
        bestGenF = pop[0].f;
        stall = 0;
      } else {
        stall++;
      }
      if (sigma < 0.01 || stall >= 5) {
        if (best) m = best.u.slice();
        sigma = 0.15;
        setupWeights();
        resetState();
        gen = 0;
        stall = 0;
        bestGenF = -1e18;
      }
    }

    var ranked = archive.slice();
    ranked.sort(function (A, B) { return B.f - A.f; });
    var cands = [];
    for (i = 0; i < ranked.length && cands.length < 3; i++) {
      if (ranked[i].f > -20) cands.push(ranked[i]);
    }
    var bestPrm = null;
    var bestScore = -1e18;
    for (i = 0; i < cands.length; i++) {
      var sc = cands[i].f;
      if (trialsLeft() > 0 && timeLeft() > 2.5) {
        var rv = evaluate(cands[i].u, 0);
        if (rv) sc = 0.5 * (cands[i].f + rv.f);
      }
      if (sc > bestScore) {
        bestScore = sc;
        bestPrm = cands[i].prm;
      }
    }
    if (bestPrm) result = bestPrm;
  } catch (e) {
    result = null;
  }
  if (!result) result = best ? best.prm : toParams(uFromParams({}));
  return result;
}

// ===================== body data (motor order, from the brief) =====================
var RW_LO = [-0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05, -0.748, -0.458, -0.392,
  -1.08, -0.183, -0.722, -0.05, -0.432, -0.265, -0.481, -0.05, -0.713, -0.375,
  -0.384, -1.149, -0.214, -0.775, -0.05];
var RW_HI = [0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286, 0.515, 0.359, 0.97,
  2.326, 1.833, 0.807, 2.192, 1.818, 0.542, 0.696, 2.167, 0.485, 0.356,
  1.032, 2.496, 1.823, 0.855, 2.289];

// Tunable magnitudes: [name, low, high, default]. Reflex signs are fixed inside policy().
// Conventions: pitch>0 forward, roll>0 right.
