  ['amp', 0.00, 0.35, 0.15],
  ['h0', -0.10, 0.35, 0.10],
  ['k0', 0.00, 0.60, 0.20],
  ['kSwing', 0.00, 1.20, 0.50],
  ['lo', -0.05, 0.15, 0.05],
  ['la', -0.15, 0.15, 0.05],
  ['lph', -1.50, 1.50, 0.00],
  ['armA', 0.00, 0.60, 0.25],
  ['kHP', 0.00, 1.20, 0.50],
  ['kAP', 0.00, 1.20, 0.50],
  ['kWP', 0.00, 1.00, 0.30],
  ['kHR', 0.00, 1.20, 0.50],
  ['kAR', 0.00, 1.20, 0.50],
  ['kWR', 0.00, 1.00, 0.25],
  ['kDP', 0.00, 0.30, 0.10],
  ['kDR', 0.00, 0.30, 0.10],
  ['kI', 0.00, 0.50, 0.10],
  ['kY', 0.00, 0.60, 0.20],
  ['kStep', 0.00, 3.00, 1.50],
  ['kpLeg', 3.00, 14.00, 7.00],
  ['kpWaist', 2.00, 10.00, 5.00],
