    evalU(uDef, 'walk');
    evalU(uDef, 'stand');
    var probes = [{ kpAnk: 2.5 }, { kpAnk: 9 }, { kHP: 0, kWP: 0 }, { kAP: 1.0, kAR: 1.0, kHR: 1.0 }];
    for (i = 0; i < probes.length; i++) evalU(uFromPrm(probes[i]), 'stand');

    // stage 1: standing (gait off) by survival and low tilt
    var bs = bestOf('stand');
    var startS = bs ? bs.u.slice() : uDef.slice();
    esRun(standDims, startS, 0.2, 56, 'stand', 8);

    // stage 2: gait on, posture taken from the best stander
    var bs2 = bestOf('stand');
    var startW = bs2 ? bs2.u.slice() : uDef.slice();
    for (i = 0; i < gaitDims.length; i++) startW[gaitDims[i]] = uDef[gaitDims[i]];
    evalU(startW, 'walk');
    esRun(gaitDims, startW, 0.2, 56, 'walk', 8);

    // stage 3: everything together, walking score
    var bw = bestOf('walk');
    var startA = bw ? bw.u.slice() : uDef.slice();
    esRun(allDims, startA, 0.08, Math.max(0, trialsLeft() - 8), 'walk', 8);
  } catch (err) {
    // keep whatever has been archived so far
  }

  // final: re-check the three best walkers once and keep the best average
  var prmOut = null;
  try {
    var walkRecs = [];
    for (i = 0; i < archive.length; i++) {
      if (archive[i].mode === 'walk') walkRecs.push(archive[i]);
    }
    walkRecs.sort(function (A, B) { return B.s - A.s; });
    var lim = Math.min(3, walkRecs.length);
    var bestAvg = -1e18;
    for (c = 0; c < lim; c++) {
      var cand2 = walkRecs[c];
      var avg = cand2.s;
      if (!stopped && trialsLeft() >= 1 && timeLeft() > 2) {
        var re = evalU(cand2.u, 'walk');
        if (re) avg = 0.5 * (cand2.s + re.s);
      }
      if (avg > bestAvg) {
        bestAvg = avg;
        prmOut = cand2.prm;
      }
    }
  } catch (err) {
    prmOut = null;
  }
  if (!prmOut) prmOut = prmFromU(uDef);
  return prmOut;
}

// ===================== body data (motor order, from the brief) =====================
var RW2_LO = [-0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05, -0.748, -0.458, -0.392,
  -1.08, -0.183, -0.722, -0.05, -0.432, -0.265, -0.481, -0.05, -0.713, -0.375,
  -0.384, -1.149, -0.214, -0.775, -0.05];
var RW2_HI = [0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286, 0.515, 0.359, 0.97,
  2.326, 1.833, 0.807, 2.192, 1.818, 0.542, 0.696, 2.167, 0.485, 0.356,
  1.032, 2.496, 1.823, 0.855, 2.289];

// Tunable parameters: [name, low, high, default, log-scaled]
var RW2_SPEC = [
  ['kAP', 0.0, 2.0, 0.9, false],      // ankle pitch balance (per rad of forward lean)
  ['kHP', 0.0, 1.0, 0.25, false],     // hip flex balance (per rad of forward lean)
  ['kWP', 0.0, 1.0, 0.3, false],      // waist pitch balance (per rad of forward lean)
  ['kAR', 0.0, 1.5, 0.5, false],      // ankle roll balance (per rad of right lean)
  ['kHR', 0.0, 1.5, 0.5, false],      // lateral pelvis balance (per rad of right lean)
  ['kWR', 0.0, 1.0, 0.3, false],      // waist roll balance (per rad of right lean)
  ['kDp', 0.0, 0.3, 0.1, false],      // pitch-rate lead (s)
  ['kDr', 0.0, 0.3, 0.05, false],     // roll-rate lead (s)
  ['kY', 0.0, 0.3, 0.1, false],       // yaw correction through the waist
  ['Kbase', 0.0, 0.6, 0.2, false],    // stance knee bend (rad)
  ['w', -0.06, 0.12, 0.0, false],     // stance width: hip-out offset of both legs (rad)
  ['H0', -0.05, 0.2, 0.1, false],     // hip flex centre of the step cycle (rad)
  ['kpAnk', 2.0, 12.0, 5.0, true],    // ankle stiffness
  ['kpHip', 1.0, 8.0, 4.0, true],     // hip stiffness
  ['kpKnee', 2.0, 10.0, 6.0, true],   // knee stiffness
  ['kpWaist', 2.0, 10.0, 5.0, true],  // waist stiffness
  ['kd', 0.0, 0.5, 0.08, false],      // joint damping (command per rad/s)
  ['f', 0.25, 1.0, 0.45, true],       // gait cycles per second
  ['A', 0.02, 0.15, 0.07, false],     // hip flex swing amplitude (rad)
  ['beta', 0.55, 0.9, 0.78, false],   // fraction of each cycle a foot is on the ground
  ['Klift', 0.0, 1.2, 0.5, false],    // swing knee bend (rad)
  ['cA', 0.02, 0.13, 0.08, false],    // pelvis shift over the stance foot (m)
  ['armA', 0.0, 0.4, 0.1, false]      // arm swing (rad)
];

function rw2Num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function rw2Clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
function rw2Frac(x) { return x - Math.floor(x); }
function rw2Smooth(x) {
  var u = rw2Clamp(x, 0, 1);
  return u * u * u * (10 - 15 * u + 6 * u * u);
}
function rw2Zeros() {
  var a = [];
  for (var i = 0; i < 25; i++) a.push(0);
  return a;
}
function rw2Params(params) {
  var p = {};
  for (var i = 0; i < RW2_SPEC.length; i++) {
    var sp = RW2_SPEC[i];
    var v = (params && typeof params === 'object') ? params[sp[0]] : undefined;
    if (typeof v !== 'number' || !isFinite(v)) v = sp[3];
    p[sp[0]] = rw2Clamp(v, sp[1], sp[2]);
  }
  return p;
}
// Lateral pelvis shape over one cycle: +1 = pelvis over the left foot, -1 = over the right foot.
// The weight moves during the double-support windows (both feet down).
function rw2Lateral(ph, beta) {
  var dd = beta - 0.5;
  if (dd < 0.02) dd = 0.02;
  if (ph < dd) return -1 + 2 * rw2Smooth(ph / dd);
  if (ph < 0.5) return 1;
  if (ph < 0.5 + dd) return 1 - 2 * rw2Smooth((ph - 0.5) / dd);
  return -1;
}

function policy(obs, params, mem) {
  try {
    if (!obs || typeof obs !== 'object') return rw2Zeros();
    if (!mem || typeof mem !== 'object') mem = {};
    var p = rw2Params(params);
    var LEG = 0.9;                       // hip-to-ankle length (m), lateral geometry only
    var t = rw2Num(obs.t, 0);

    var roll = 0, pitch = 0, yaw = 0;
    var ori = obs.orientation;
    if (ori && typeof ori.length === 'number' && ori.length >= 3) {
      roll = rw2Num(ori[0], 0);
      pitch = rw2Num(ori[1], 0);
      yaw = rw2Num(ori[2], 0);
    }
    var gxr = 0, gyr = 0;
    var gyro = obs.gyro;
    if (gyro && typeof gyro.length === 'number' && gyro.length >= 2) {
      gxr = rw2Num(gyro[0], 0);
      gyr = rw2Num(gyro[1], 0);
    }
    var q = (obs.joints && typeof obs.joints.length === 'number') ? obs.joints : [];
    var qd = (obs.speeds && typeof obs.speeds.length === 'number') ? obs.speeds : [];
    var fL = 0, fR = 0;
    if (obs.feet && typeof obs.feet.length === 'number' && obs.feet.length >= 2) {
      fL = Math.max(0, rw2Num(obs.feet[0], 0));
      fR = Math.max(0, rw2Num(obs.feet[1], 0));
    }

    var first = !mem.init;
    var dtNow = 0.02;
    if (first) {
      mem.init = true;
      mem.lastT = t;
      mem.ph = 0;
      mem.hold = 0;
      mem.pf = pitch;
      mem.rf = roll;
      mem.yf = yaw;
      mem.pr = gyr;
      mem.rr = gxr;
    } else {
      dtNow = t - mem.lastT;
      if (!(dtNow > 0.0005)) dtNow = 0.02;
      if (dtNow > 0.1) dtNow = 0.1;
      mem.lastT = t;
      mem.pf = 0.5 * mem.pf + 0.5 * pitch;
      mem.rf = 0.5 * mem.rf + 0.5 * roll;
      mem.yf = 0.5 * mem.yf + 0.5 * yaw;
      mem.pr = 0.5 * mem.pr + 0.5 * gyr;
      mem.rr = 0.5 * mem.rr + 0.5 * gxr;
    }

    var pc = mem.pf + p.kDp * mem.pr;    // + = leaning forward
    var rc = mem.rf + p.kDr * mem.rr;    // + = leaning right
    var yc = mem.yf;
    var tilt = Math.max(Math.abs(mem.pf), Math.abs(mem.rf));
    var sfac = rw2Clamp(1 - (tilt - 0.2) / 0.25, 0.3, 1);
    var rp = rw2Clamp(t / 0.5, 0, 1);            // posture ramp-in
    var rg = rw2Clamp((t - 0.8) / 1.2, 0, 1);    // gait ramp-in
    var beta = p.beta;
    var dd = beta - 0.5;

    if (!first) {
      // gait phase: advances at f; held for a bounded time just before a foot lifts
      // while the weight has not yet moved onto the foot that stays down
      var distR = rw2Frac(dd - mem.ph);
      var distL = rw2Frac(beta - mem.ph);
      var tot = fL + fR;
      var sL = (tot > 1e-6) ? fL / tot : 0.5;
      var share = (distR < distL) ? sL : (1 - sL);
      var near = Math.min(distR, distL);
      var adv = sfac;
      if (near < 0.04 && share < 0.6 && mem.hold < 0.4) {
        adv = 0;
        mem.hold += dtNow;
      } else if (near > 0.08) {
        mem.hold = 0;
      }
      mem.ph = rw2Frac(mem.ph + adv * p.f * dtNow);
    }
    var ph = mem.ph;

    var cLat = rg * p.cA * rw2Lateral(ph, beta);   // + = pelvis over the left foot
    var tgt = rw2Zeros();
    var rawL = 0, rawR = 0;
    var legs = [{ base: 3, side: 1, off: 0 }, { base: 14, side: -1, off: 0.5 }];
    for (var li = 0; li < 2; li++) {
      var lg = legs[li];
      var pX = rw2Frac(ph + lg.off);
      var raw = 0, bump = 0;
      if (pX < beta) {
        raw = p.A - 2 * p.A * (pX / beta);           // stance: hip sweeps forward to back
      } else {
        var v = (pX - beta) / (1 - beta);
        var se = -(1 - beta) / beta;                 // foot is still in the world at touchdown
        var gv = se * (2 * v * v * v - 3 * v * v + v) + (3 * v * v - 2 * v * v * v);
        raw = -p.A + 2 * p.A * gv;                   // swing: back to front
        bump = Math.sin(Math.PI * v);                // knee lift
      }
      var Hx = rp * p.H0 + rg * (raw + 0.5 * p.Klift * bump) + p.kHP * pc * rp;
      var Kx = rp * p.Kbase + rg * p.Klift * bump;
      var outT = (lg.side > 0)
        ? (rp * p.w - cLat / LEG - p.kHR * rc * rp)
        : (rp * p.w + cLat / LEG + p.kHR * rc * rp);
      var ankP = Kx - Hx - p.kAP * pc * rp;
      var ankR = (lg.side > 0) ? (-outT + p.kAR * rc * rp) : (-outT - p.kAR * rc * rp);
      tgt[lg.base] = Hx;
      tgt[lg.base + 1] = outT;
      tgt[lg.base + 2] = 0;
      tgt[lg.base + 3] = Kx;
      tgt[lg.base + 4] = ankP;
      tgt[lg.base + 5] = ankR;
      tgt[lg.base + 6] = 0;
      var nrm = (p.A > 1e-6) ? rw2Clamp(raw / p.A, -1, 1) : 0;
      if (li === 0) rawL = nrm; else rawR = nrm;
    }

    tgt[0] = -p.kWP * pc * rp;
    tgt[1] = -p.kWR * rc * rp;
    tgt[2] = -p.kY * yc * rp;
    tgt[10] = p.armA * rg * rawR;
    tgt[11] = 0.15 * rp;
    tgt[13] = 0.3 * rp;
    tgt[21] = p.armA * rg * rawL;
    tgt[22] = 0.15 * rp;
    tgt[24] = 0.3 * rp;

    var out = [];
    for (var i = 0; i < 25; i++) {
      var lo = RW2_LO[i] + 0.02;
      var hi = RW2_HI[i] - 0.02;
      var tg = rw2Clamp(rw2Num(tgt[i], 0), lo, hi);
      var qi = rw2Num(q[i], 0);
      var qdi = rw2Num(qd[i], 0);
      var kp;
      if (i <= 2) kp = p.kpWaist;
      else if (i === 3 || i === 4 || i === 14 || i === 15) kp = p.kpHip;
      else if (i === 5 || i === 16) kp = 0.5 * p.kpHip;
      else if (i === 6 || i === 17) kp = p.kpKnee;
      else if (i === 7 || i === 18) kp = p.kpAnk;
      else if (i === 8 || i === 19) kp = 0.7 * p.kpAnk;
      else if (i === 9 || i === 20) kp = 0.5 * p.kpAnk;
      else kp = 2;
      var u = kp * (tg - qi) - p.kd * qdi;
      if (!isFinite(u)) u = 0;
      out.push(rw2Clamp(u, -1, 1));
    }
    return out;
  } catch (e) {
    return rw2Zeros();
  }
}

function learn(lab) {
  var n = RW2_SPEC.length;
  var archive = [];
  var stopped = false;
  var i;
  var idx = {};
  for (i = 0; i < n; i++) idx[RW2_SPEC[i][0]] = i;

  function num(x, dflt) { var v = Number(x); return isFinite(v) ? v : dflt; }
  function clamp01(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }
  function clampN(x, lo, hi) { return x < lo ? lo : (x > hi ? hi : x); }
  function trialsLeft() {
    if (!lab || typeof lab.trialsLeft !== 'function') return 200 - archive.length;
    try { return num(lab.trialsLeft(), 0); } catch (err) { return 0; }
  }
  function timeLeft() {
    if (!lab || typeof lab.timeLeft !== 'function') return 1e9;
    try { return num(lab.timeLeft(), 0); } catch (err) { return 0; }
  }
  function gauss() {
    var u1 = Math.random(), u2 = Math.random();
    if (u1 < 1e-12) u1 = 1e-12;
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }
  function prmFromU(u) {
    var o = {};
    for (var q = 0; q < n; q++) {
      var sp = RW2_SPEC[q];
      var x = clamp01(num(u[q], 0.5));
      o[sp[0]] = sp[4] ? sp[1] * Math.pow(sp[2] / sp[1], x) : sp[1] + x * (sp[2] - sp[1]);
    }
    return o;
  }
  function uFromPrm(prm) {
    var u = [];
    for (var q = 0; q < n; q++) {
      var sp = RW2_SPEC[q];
      var v = (prm && typeof prm[sp[0]] === 'number' && isFinite(prm[sp[0]])) ? prm[sp[0]] : sp[3];
      var x = sp[4] ? Math.log(v / sp[1]) / Math.log(sp[2] / sp[1]) : (v - sp[1]) / (sp[2] - sp[1]);
      if (!(x === x)) x = 0.5;
      u.push(clamp01(x));
    }
    return u;
  }
  function traceStats(r) {
    var mx = 0, sum = 0, cnt = 0, side = 0;
    var tr = (r && r.trace && typeof r.trace.length === 'number') ? r.trace : [];
    for (var y = 0; y < tr.length; y++) {
      var row = tr[y];
      if (row && typeof row.length === 'number' && row.length >= 6) {
        var tl = Math.max(Math.abs(num(row[4], 0)), Math.abs(num(row[5], 0)));
        if (tl > mx) mx = tl;
        sum += tl;
        cnt++;
        var sd = Math.abs(num(row[3], 0));
        if (sd > side) side = sd;
      }
    }
    return { maxT: mx, meanT: cnt > 0 ? sum / cnt : 0, side: side };
  }
  function score(r, mode) {
    if (!r || typeof r !== 'object' || r.outcome === 'exploit' || r.outcome === 'invalid' || r.outcome === 'error') return -20;
    var tm = clampN(num(r.time, 0), 0, 10);
    var dist = num(r.distance, 0);
    var st = traceStats(r);
    var sc;
    if (mode === 'stand') {
      sc = tm + (r.outcome === 'finished' ? 2 : 0) - 3 * st.meanT - 2 * Math.max(0, st.side - 0.8);
    } else {
      sc = dist + 0.3 * tm + (r.outcome === 'finished' ? 1 : 0)
        - 2 * Math.max(0, st.maxT - 0.5) - 1.5 * Math.max(0, st.side - 1.0);
    }
    if (!isFinite(sc)) sc = -20;
    return sc;
  }
  function evalU(u, mode) {
    if (stopped || trialsLeft() < 1 || timeLeft() < 1.5) return null;
    var prm = prmFromU(u);
    if (mode === 'stand') { prm.A = 0; prm.cA = 0; prm.Klift = 0; prm.armA = 0; }
    var r = null;
    try { r = lab.trial(prm); } catch (err) { stopped = true; return null; }
    var ok = (r && typeof r === 'object');
    var rec = {
      u: u.slice(),
      prm: prm,
      mode: mode,
      s: score(r, mode),
      outcome: ok ? String(r.outcome) : 'none',
      time: ok ? num(r.time, 0) : 0,
      dist: ok ? num(r.distance, 0) : 0
    };
    if (!isFinite(rec.s)) rec.s = -20;
    archive.push(rec);
    return rec;
  }
  function bestOf(mode) {
    var best = null;
    for (var y = 0; y < archive.length; y++) {
      var rr = archive[y];
      if (rr.mode === mode && (best === null || rr.s > best.s)) best = rr;
    }
    return best;
  }
  function esRun(dims, start, sigma0, budget, mode, lam) {
    var m = start.slice();
    var sigma = sigma0;
    var mu = Math.max(1, Math.floor(lam / 2));
    var wts = [];
    var wsum = 0;
    var z, g, d, e;
    for (z = 0; z < mu; z++) { wts.push(Math.log(mu + 0.5) - Math.log(z + 1)); wsum += wts[z]; }
    for (z = 0; z < mu; z++) wts[z] = wts[z] / wsum;
    var used = 0;
    var bestSeen = -1e18;
    while (used + lam <= budget) {
      if (stopped || trialsLeft() < 1 || timeLeft() < 1.5) break;
      var pop = [];
      for (g = 0; g < lam; g++) {
        var cand = m.slice();
        for (d = 0; d < dims.length; d++) {
          cand[dims[d]] = clamp01(m[dims[d]] + sigma * gauss());
        }
        var rec = evalU(cand, mode);
        if (!rec) break;
        pop.push(rec);
        used++;
      }
      if (pop.length === 0) break;
      pop.sort(function (A, B) { return B.s - A.s; });
      var cnt = Math.min(mu, pop.length);
      var ws = 0;
      for (z = 0; z < cnt; z++) ws += wts[z];
      var nm = m.slice();
      for (e = 0; e < dims.length; e++) {
        var acc = 0;
        for (z = 0; z < cnt; z++) acc += wts[z] * pop[z].u[dims[e]];
        nm[dims[e]] = acc / ws;
      }
      m = nm;
      if (pop[0].s > bestSeen + 0.05) {
        bestSeen = pop[0].s;
        sigma = Math.min(0.3, sigma * 1.2);
      } else {
        sigma = Math.max(0.03, sigma * 0.85);
      }
      if (pop.length < lam) break;
    }
    return m;
  }

  var uDef = uFromPrm({});
  var allDims = [];
  for (i = 0; i < n; i++) allDims.push(i);
  var standNames = ['kAP', 'kHP', 'kWP', 'kAR', 'kHR', 'kWR', 'kDp', 'kDr', 'kY', 'Kbase', 'w', 'H0',
    'kpAnk', 'kpHip', 'kpKnee', 'kpWaist', 'kd'];
  var gaitNames = ['f', 'A', 'beta', 'Klift', 'cA', 'armA'];
  var standDims = [], gaitDims = [];
  for (i = 0; i < standNames.length; i++) standDims.push(idx[standNames[i]]);
  for (i = 0; i < gaitNames.length; i++) gaitDims.push(idx[gaitNames[i]]);

  try {
    // stage 0: reference walk, reference stand, and four standing probes
    evalU(uDef, 'walk');
    evalU(uDef, 'stand');
    var probes = [
      { kpAnk: 3.0 },
      { kpAnk: 8.0, kpHip: 6.0 },
      { kAP: 1.5, kHP: 0.5, kHR: 0.9 },
      { Kbase: 0.35, H0: 0.17, kpKnee: 8.0 }
    ];
    for (i = 0; i < probes.length; i++) evalU(uFromPrm(probes[i]), 'stand');

    // stage 1: balance (gait off) by survival and low tilt
    var bs = bestOf('stand');
    esRun(standDims, bs ? bs.u.slice() : uDef.slice(), 0.2, 40, 'stand', 8);

    // stage 2: gait parameters by walking distance, balance from the best stander
    var bs2 = bestOf('stand');
    var startW = bs2 ? bs2.u.slice() : uDef.slice();
    for (i = 0; i < gaitDims.length; i++) startW[gaitDims[i]] = uDef[gaitDims[i]];
    evalU(startW, 'walk');
    esRun(gaitDims, startW, 0.2, 90, 'walk', 8);

    // stage 3: everything together by walking distance
    var bw = bestOf('walk');
    var startA = bw ? bw.u.slice() : uDef.slice();
    esRun(allDims, startA, 0.08, Math.max(0, trialsLeft() - 6), 'walk', 8);
  } catch (err) {
    // keep whatever has been archived so far
  }

  // final: re-check the three best walkers once and keep the best average
  var prmOut = null;
  try {
    var walkRecs = [];
    for (i = 0; i < archive.length; i++) {
      if (archive[i].mode === 'walk') walkRecs.push(archive[i]);
    }
    walkRecs.sort(function (A, B) { return B.s - A.s; });
    var lim = Math.min(3, walkRecs.length);
    var bestAvg = -1e18;
    for (var c = 0; c < lim; c++) {
      var cand2 = walkRecs[c];
      var avg = cand2.s;
      if (!stopped && trialsLeft() >= 1 && timeLeft() > 2) {
        var re = evalU(cand2.u, 'walk');
        if (re) avg = 0.5 * (cand2.s + re.s);
      }
      if (avg > bestAvg) {
        bestAvg = avg;
        prmOut = cand2.prm;
      }
    }
  } catch (err) {
    prmOut = null;
  }
  if (!prmOut) prmOut = prmFromU(uDef);
  return prmOut;
}

// ===================== body data (motor order, from the brief) =====================
var RB_LO = [-0.407, -0.342, -0.515, -0.567, -0.268, -0.544, -0.05, -0.748, -0.458, -0.392,
  -1.08, -0.183, -0.722, -0.05, -0.432, -0.265, -0.481, -0.05, -0.713, -0.375,
  -0.384, -1.149, -0.214, -0.775, -0.05];
var RB_HI = [0.822, 0.441, 0.616, 1.596, 0.609, 0.777, 2.286, 0.515, 0.359, 0.97,
  2.326, 1.833, 0.807, 2.192, 1.818, 0.542, 0.696, 2.167, 0.485, 0.356,
  1.032, 2.496, 1.823, 0.855, 2.289];

// Tunable parameters: [name, low, high, default, log-scaled]
var RB_SPEC = [
  ['kpA', 2.0, 14.0, 6.0, true],     // ankle stiffness (command per rad)
  ['kpH', 1.0, 12.0, 5.0, true],     // hip flex and hip out stiffness
  ['kpK', 2.0, 14.0, 6.0, true],     // knee stiffness
  ['kpW', 1.5, 10.0, 4.0, true],     // waist stiffness
  ['Td', 0.0, 0.25, 0.08, false],    // derivative time (s): kd = Td * kp
  ['Lp', 0.0, 0.15, 0.05, false],    // pitch lead (s), cancels command delay
  ['Lr', 0.0, 0.15, 0.04, false],    // roll lead (s)
  ['gAP', -0.5, 2.0, 0.6, false],    // ankle pitch: toe-down per rad of forward lean
  ['gHP', -1.0, 1.0, 0.2, false],    // hip flex per rad of forward lean (sign free)
  ['gWP', -1.0, 1.0, -0.2, false],   // waist pitch per rad of forward lean
  ['gAR', -1.0, 2.0, 0.4, false],    // ankle roll per rad of right lean (CoP shift)
  ['gHR', -1.0, 2.0, 0.4, false],    // hip out per rad of right lean (pelvis shift)
  ['gWR', -1.0, 1.0, 0.2, false],    // waist roll per rad of right lean
  ['Kb', 0.0, 0.5, 0.2, false],      // knee bend while standing (rad)
  ['H0', -0.2, 0.3, 0.12, false],    // hip flex base (rad)
  ['w', -0.05, 0.15, 0.02, false],   // stance width: hip out of both legs (rad)
  ['gY', 0.0, 0.3, 0.1, false],      // yaw correction through the waist
  ['f', 0.2, 1.0, 0.45, true],       // gait cycles per second
  ['A', 0.0, 0.15, 0.07, false],     // hip sweep amplitude (rad)
  ['beta', 0.55, 0.92, 0.8, false],  // fraction of a cycle each foot is down
  ['Klift', 0.0, 1.2, 0.5, false],   // swing knee lift (rad)
  ['cA', 0.0, 0.14, 0.08, false],    // pelvis shift over the stance foot (m)
  ['armA', 0.0, 0.35, 0.12, false],  // arm swing (rad)
  ['hold', 0.4, 0.95, 0.7, false]    // weight share needed before a foot lifts
];
var RB_STAND = ['kpA', 'kpH', 'kpK', 'kpW', 'Td', 'Lp', 'Lr', 'gAP', 'gHP', 'gWP',
  'gAR', 'gHR', 'gWR', 'Kb', 'H0', 'w'];
var RB_GAIT = ['f', 'A', 'beta', 'Klift', 'cA', 'armA', 'hold', 'gY'];

function rbNum(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function rbClamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
function rbFrac(x) { return x - Math.floor(x); }
function rbSmooth(x) { var u = rbClamp(x, 0, 1); return u * u * u * (10 - 15 * u + 6 * u * u); }
function rbZeros() { var a = []; for (var i = 0; i < 25; i++) a.push(0); return a; }

function rbParams(params) {
  var p = {};
  for (var i = 0; i < RB_SPEC.length; i++) {
    var sp = RB_SPEC[i];
    var v = (params && typeof params === 'object') ? params[sp[0]] : undefined;
    if (typeof v !== 'number' || !isFinite(v)) v = sp[3];
    p[sp[0]] = rbClamp(v, sp[1], sp[2]);
  }
  return p;
}

// lateral pelvis shape over one cycle: +1 = over the left foot, -1 = over the right foot
function rbLat(ph, beta) {
  var dd = beta - 0.5;
  if (dd < 0.02) dd = 0.02;
  if (ph < dd) return -1 + 2 * rbSmooth(ph / dd);
  if (ph < 0.5) return 1;
  if (ph < 0.5 + dd) return 1 - 2 * rbSmooth((ph - 0.5) / dd);
  return -1;
}

function policy(obs, params, mem) {
  try {
    if (!obs || typeof obs !== 'object') return rbZeros();
    if (!mem || typeof mem !== 'object') mem = {};
    var p = rbParams(params);
    var LEG = 0.9;
    var t = rbNum(obs.t, 0);

    var roll = 0, pitch = 0, yaw = 0;
    var ori = obs.orientation;
    if (ori && typeof ori.length === 'number' && ori.length >= 3) {
      roll = rbNum(ori[0], 0);
      pitch = rbNum(ori[1], 0);
      yaw = rbNum(ori[2], 0);
    }
    var gxr = 0, gyr = 0;
    var gyro = obs.gyro;
    if (gyro && typeof gyro.length === 'number' && gyro.length >= 2) {
      gxr = rbNum(gyro[0], 0);
      gyr = rbNum(gyro[1], 0);
    }
    var q = (obs.joints && typeof obs.joints.length === 'number') ? obs.joints : [];
    var qd = (obs.speeds && typeof obs.speeds.length === 'number') ? obs.speeds : [];
    var fL = 0, fR = 0;
    if (obs.feet && typeof obs.feet.length === 'number' && obs.feet.length >= 2) {
      fL = Math.max(0, rbNum(obs.feet[0], 0));
      fR = Math.max(0, rbNum(obs.feet[1], 0));
    }

    var first = !mem.init;
    var dt = 0.02;
    if (first) {
      mem.init = true;
      mem.lastT = t;
      mem.ph = 0;
      mem.hold = 0;
      mem.gFac = 1;
      mem.pf = pitch;
      mem.rf = roll;
      mem.yf = yaw;
      mem.pr = gyr;
      mem.rr = gxr;
    } else {
      dt = t - mem.lastT;
      if (!(dt > 0.0005)) dt = 0.02;
      if (dt > 0.1) dt = 0.1;
      mem.lastT = t;
      var kf = 1 - Math.exp(-dt / 0.025);
      mem.pf += kf * (pitch - mem.pf);
      mem.rf += kf * (roll - mem.rf);
      mem.yf += kf * (yaw - mem.yf);
      mem.pr += kf * (gyr - mem.pr);
      mem.rr += kf * (gxr - mem.rr);
    }

    var pc = mem.pf + p.Lp * mem.pr;     // + = leaning forward
    var rc = mem.rf + p.Lr * mem.rr;     // + = leaning right
    var tilt = Math.max(Math.abs(mem.pf), Math.abs(mem.rf));
    var gT = rbClamp((0.75 - tilt) / 0.2, 0, 1);   // gait pauses while the torso is far over
    if (!first) {
      var kg = 1 - Math.exp(-dt / 0.25);
      mem.gFac += kg * (gT - mem.gFac);
    }
    var gF = mem.gFac;
    var rp = rbClamp(t / 0.5, 0, 1);                 // posture ramp-in
    var rg = rbClamp((t - 0.8) / 1.2, 0, 1) * gF;    // gait ramp-in
    var beta = p.beta;

    if (!first) {
      var dL = rbFrac(beta - mem.ph);          // cycles until the left foot lifts
      var dR = rbFrac(beta - 0.5 - mem.ph);    // cycles until the right foot lifts
      var tot = fL + fR;
      var sL = (tot > 1e-6) ? fL / tot : 0.5;
      var nearL = dL < 0.04, nearR = dR < 0.04;
      var adv = gF;
      if (nearL && (1 - sL) < p.hold && mem.hold < 0.6) {
        adv = 0;
        mem.hold += dt;
      } else if (nearR && sL < p.hold && mem.hold < 0.6) {
        adv = 0;
        mem.hold += dt;
      } else if (!nearL && !nearR) {
        mem.hold = 0;
      }
      mem.ph = rbFrac(mem.ph + adv * p.f * dt);
    }
    var ph = mem.ph;
    var cLat = rg * p.cA * rbLat(ph, beta);   // + = pelvis over the left foot

    var tgt = rbZeros();
    var nrmL = 0, nrmR = 0;
    for (var li = 0; li < 2; li++) {
      var side = (li === 0) ? 1 : -1;
      var base = (li === 0) ? 3 : 14;
      var pX = rbFrac(ph + ((li === 0) ? 0 : 0.5));
      var raw = 0, bump = 0;
      if (pX < beta) {
        raw = p.A * (1 - 2 * pX / beta);                 // stance: hip sweeps front to back
      } else {
        var v = (pX - beta) / (1 - beta);
        var se = -(1 - beta) / beta;
        var gv = se * (2 * v * v * v - 3 * v * v + v) + (3 * v * v - 2 * v * v * v);
        raw = p.A * (2 * gv - 1);                        // swing: back to front
        bump = Math.sin(Math.PI * v);                    // knee lift
      }
      var nrm = (p.A > 1e-6) ? rbClamp(raw / p.A, -1, 1) : 0;
      if (li === 0) nrmL = nrm; else nrmR = nrm;
      var Hx = rp * p.H0 + rg * (raw + 0.5 * p.Klift * bump) + p.gHP * pc * rp;
      var Kx = rp * p.Kb + rg * p.Klift * bump;
      var outT = rp * p.w - side * (cLat / LEG + p.gHR * rc * rp);
      tgt[base] = Hx;
      tgt[base + 1] = outT;
      tgt[base + 3] = Kx;
      tgt[base + 4] = Kx - Hx - p.gAP * pc * rp;       // flat sole plus pitch reflex
      tgt[base + 5] = -outT + side * p.gAR * rc * rp;  // flat sole plus roll reflex
    }
    tgt[0] = p.gWP * pc * rp;
    tgt[1] = -p.gWR * rc * rp;
    tgt[2] = -p.gY * mem.yf * rp;
    tgt[10] = p.armA * nrmR * rg;      // left arm swings with the right leg
    tgt[11] = 0.15 * rp;
    tgt[13] = 0.3 * rp;
    tgt[21] = p.armA * nrmL * rg;      // right arm swings with the left leg
    tgt[22] = 0.15 * rp;
    tgt[24] = 0.3 * rp;

    var out = [];
    for (var i = 0; i < 25; i++) {
      var lo = RB_LO[i] + 0.02;
      var hi = RB_HI[i] - 0.02;
      var tg = rbClamp(rbNum(tgt[i], 0), lo, hi);
      var qi = rbNum(q[i], 0);
      var qdi = rbNum(qd[i], 0);
      var kp;
      if (i <= 2) kp = p.kpW;
      else if (i === 3 || i === 4 || i === 14 || i === 15) kp = p.kpH;
      else if (i === 5 || i === 16) kp = 0.5 * p.kpH;
      else if (i === 6 || i === 17) kp = p.kpK;
      else if (i === 7 || i === 18) kp = p.kpA;
      else if (i === 8 || i === 19) kp = 0.7 * p.kpA;
      else if (i === 9 || i === 20) kp = 0.5 * p.kpA;
      else kp = 2.0;
      var u = kp * (tg - qi) - p.Td * kp * qdi;     // PD with derivative damping
      if (!isFinite(u)) u = 0;
      out.push(rbClamp(u, -1, 1));
    }
    return out;
  } catch (e) {
    return rbZeros();
  }
}

function learn(lab) {
  var n = RB_SPEC.length;
  var idx = {};
  var i, k;
  for (i = 0; i < n; i++) idx[RB_SPEC[i][0]] = i;
  var archive = [];
  var stopped = false;

  function num(x, d) { var v = Number(x); return isFinite(v) ? v : d; }
  function clamp01(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }
  function trialsLeft() {
    if (!lab || typeof lab.trialsLeft !== 'function') return 200 - archive.length;
    try { return num(lab.trialsLeft(), 0); } catch (e) { return 0; }
  }
  function timeLeft() {
    if (!lab || typeof lab.timeLeft !== 'function') return 1e9;
    try { return num(lab.timeLeft(), 0); } catch (e) { return 0; }
  }
  function prmFromU(u) {
    var o = {};
    for (var q = 0; q < n; q++) {
      var sp = RB_SPEC[q];
      var x = clamp01(num(u[q], 0.5));
      o[sp[0]] = sp[4] ? sp[1] * Math.pow(sp[2] / sp[1], x) : sp[1] + x * (sp[2] - sp[1]);
    }
    return o;
  }
  function uFromPrm(prm) {
    var u = [];
    for (var q = 0; q < n; q++) {
      var sp = RB_SPEC[q];
      var v = (prm && typeof prm[sp[0]] === 'number' && isFinite(prm[sp[0]])) ? prm[sp[0]] : sp[3];
      var x = sp[4] ? Math.log(v / sp[1]) / Math.log(sp[2] / sp[1]) : (v - sp[1]) / (sp[2] - sp[1]);
      if (!(x === x)) x = 0.5;
      u.push(clamp01(x));
    }
    return u;
  }
  function uOf(name, value) {
    var o = {};
    o[name] = value;
    return uFromPrm(o)[idx[name]];
  }
  function traceStats(r) {
    var tr = (r && r.trace && typeof r.trace.length === 'number') ? r.trace : [];
    var sum = 0, cnt = 0, mx = 0, side = 0;
    for (var y = 0; y < tr.length; y++) {
      var row = tr[y];
      if (row && typeof row.length === 'number' && row.length >= 6) {
        var tl = Math.abs(num(row[4], 0)) + Math.abs(num(row[5], 0));
        sum += tl;
        cnt++;
        if (tl > mx) mx = tl;
        var sd = Math.abs(num(row[3], 0));
        if (sd > side) side = sd;
      }
    }
    return { meanT: cnt > 0 ? sum / cnt : 0.5, maxT: mx, maxS: side };
  }
  function score(r, mode) {
    if (!r || typeof r !== 'object') return -100;
    var oc = String(r.outcome);
    if (oc === 'exploit' || oc === 'invalid' || oc === 'error') return -100;
    var T = Math.min(10, Math.max(0, num(r.time, 0)));
    var fin = (oc === 'finished');
    var st = traceStats(r);
    var s;
    if (mode === 'stand') {
      s = T + (fin ? 1.5 : 0) - 5 * st.meanT - Math.max(0, st.maxT - 0.8) - Math.max(0, st.maxS - 0.6);
    } else {
      s = num(r.distance, 0) + (fin ? 0.8 : 0) + 0.1 * T
        - 3 * Math.max(0, st.meanT - 0.25) - 1.5 * Math.max(0, st.maxS - 1.0);
    }
    return isFinite(s) ? s : -100;
  }
  function run(u, mode) {
    if (stopped) return null;
    if (trialsLeft() < 1 || timeLeft() < 2) { stopped = true; return null; }
    var prm = prmFromU(u);
    var send = prmFromU(u);
    if (mode === 'stand') { send.A = 0; send.cA = 0; send.Klift = 0; send.armA = 0; }
    var r = null;
    try { r = lab.trial(send); } catch (e) { stopped = true; return null; }
    var ok = (r && typeof r === 'object');
    var rec = {
      u: u.slice(),
      prm: prm,
      mode: mode,
      s: score(r, mode),
      outcome: ok ? String(r.outcome) : 'none',
      time: ok ? num(r.time, 0) : 0,
      dist: ok ? num(r.distance, 0) : 0
    };
    archive.push(rec);
    return rec;
  }
  function bestOf(mode) {
    var b = null;
    for (var y = 0; y < archive.length; y++) {
      var rr = archive[y];
      if (rr.mode === mode && (b === null || rr.s > b.s)) b = rr;
    }
    return b;
  }
  // random sparse sign moves with an adaptive step (1+1 evolution)
  function search(dims, start, step0, budget, mode) {
    var cur = start.slice();
    var seed = run(cur, mode);
    if (!seed) return cur;
    var curS = seed.s;
    var step = step0;
    var used = 1;
    while (used < budget) {
      if (stopped || trialsLeft() < 1 || timeLeft() < 2) break;
      var cand = cur.slice();
      var m = 1 + Math.floor(Math.random() * Math.min(4, dims.length));
      for (var e = 0; e < m; e++) {
        var d = dims[Math.floor(Math.random() * dims.length)];
        var sg = (Math.random() < 0.5) ? -1 : 1;
        cand[d] = clamp01(cand[d] + sg * step * (0.5 + Math.random()));
      }
      var rec = run(cand, mode);
      used++;
      if (!rec) break;
      if (rec.s > curS + 1e-9) {
        cur = cand;
        curS = rec.s;
        step = Math.min(0.3, step * 1.25);
      } else {
        step = Math.max(0.015, step * 0.93);
      }
    }
    return cur;
  }

  var uDef = uFromPrm({});
  var total = trialsLeft();
  if (!(total > 0)) total = 200;
  var standDims = [], gaitDims = [], allDims = [];
  for (i = 0; i < RB_STAND.length; i++) standDims.push(idx[RB_STAND[i]]);
  for (i = 0; i < RB_GAIT.length; i++) gaitDims.push(idx[RB_GAIT[i]]);
  for (i = 0; i < n; i++) allDims.push(i);

  try {
    // stage 0: sign probes for the balance reflexes while standing (gait off)
    var probes = [[null, 0], ['gHP', -0.25], ['gHR', -0.2], ['gWP', 0.2]];
    var bestProbe = null;
    for (k = 0; k < probes.length; k++) {
      var pu = uDef.slice();
      if (probes[k][0] !== null) pu[idx[probes[k][0]]] = uOf(probes[k][0], probes[k][1]);
      var pr = run(pu, 'stand');
      if (!pr) break;
      if (bestProbe === null || pr.s > bestProbe.s) bestProbe = pr;
    }
    var startStand = bestProbe ? bestProbe.u.slice() : uDef.slice();

    // stage 1: balance (gait off) by survival and low tilt
    search(standDims, startStand, 0.22, Math.floor(0.34 * total), 'stand');

    // stage 2: gait with the best balance, by walking distance
    var bS = bestOf('stand');
    var uW = bS ? bS.u.slice() : uDef.slice();
    for (k = 0; k < gaitDims.length; k++) uW[gaitDims[k]] = uDef[gaitDims[k]];
    search(allDims, uW, 0.15, Math.floor(0.40 * total), 'walk');

    // stage 3: refine walking with everything
    var bW = bestOf('walk');
    var uR = bW ? bW.u.slice() : uDef.slice();
    var rest = trialsLeft() - 8;
    if (rest > 4) search(allDims, uR, 0.05, rest, 'walk');
  } catch (err) {
    // keep whatever has been archived so far
  }

  // final: re-check the three best walkers once and keep the best average
  var prmOut = null;
  try {
    var walkRecs = [];
    for (i = 0; i < archive.length; i++) {
      if (archive[i].mode === 'walk') walkRecs.push(archive[i]);
    }
    walkRecs.sort(function (A, B) { return B.s - A.s; });
    var lim = Math.min(3, walkRecs.length);
    var bestAvg = -1e18;
    for (var c = 0; c < lim; c++) {
      var cand2 = walkRecs[c];
      var avg = cand2.s;
      if (!stopped && trialsLeft() >= 1 && timeLeft() > 2) {
        var re = run(cand2.u, 'walk');
        if (re) avg = 0.5 * (cand2.s + re.s);
      }
      if (avg > bestAvg) {
        bestAvg = avg;
        prmOut = cand2.prm;
      }
    }
  } catch (err2) {
    prmOut = null;
  }
  if (!prmOut) {
    var bS2 = bestOf('stand');
    prmOut = bS2 ? bS2.prm : prmFromU(uDef);
  }
  return prmOut;
}
